import type { RawQ } from "../types";
// Scholar tier (Mutaqaddim and ʿĀlim) uṣūl al-fiqh: commands and prohibitions, general and specific, qiyās and its cause, disputed sources, ijmāʿ, naskh and preference, maqāṣid, ijtihād and taqlīd, with the positions of the four schools framed as who held what. Draft content, needs scholarly review.
export const QS: RawQ[] = [
{ id: "xuf-001", s: "fiqh", g: 4, d: 6, t: ["usul", "amr", "wujub"], tr: ["comparative", "jumhur"], src: "al-Ghazālī, al-Mustaṣfā; al-Āmidī, al-Iḥkām fī Uṣūl al-Aḥkām; al-Shīrāzī, al-Lumaʿ",
    en: ["What do most uṣūlīs hold about an unqualified command (amr) such as an imperative with no accompanying indication?", ["That it indicates obligation (wujūb) unless an indication shows otherwise", "That it always indicates only recommendation", "That it always indicates permission", "That it indicates nothing until the Prophet explains it"], "The majority of the Shāfiʿī, Ḥanafī, Mālikī and Ḥanbalī uṣūlīs hold that the bare imperative form indicates obligation by default, shifting to recommendation, permission or other senses only through a contextual indication (qarīna). Some held it indicates recommendation as the certain minimum, and others suspended judgment (waqf), and the discussion appears in all the major manuals."],
    de: ["Was vertreten die meisten Uṣūlīs zu einem unbedingten Befehl (amr), etwa einem Imperativ ohne begleitenden Hinweis?", ["Dass er Pflicht (wuǧūb) anzeigt, sofern kein Hinweis etwas anderes zeigt", "Dass er immer nur Empfehlung anzeigt", "Dass er immer Erlaubnis anzeigt", "Dass er nichts anzeigt, bis der Prophet ihn erklärt"], "Die Mehrheit der schāfiʿitischen, ḥanafitischen, mālikitischen und ḥanbalitischen Uṣūlīs vertritt, dass die bloße Imperativform standardmäßig Pflicht anzeigt und nur durch einen Kontexthinweis (qarīna) zu Empfehlung, Erlaubnis oder anderen Bedeutungen wechselt. Manche hielten Empfehlung als sicheres Minimum, andere enthielten sich des Urteils (waqf), und die Erörterung steht in allen großen Handbüchern."],
    ar: ["ماذا يرى أكثر الأصوليين في الأمر المطلق أي صيغة الأمر المجردة عن القرينة؟", ["أنه يدل على الوجوب ما لم تدل قرينة على غيره", "أنه يدل دائمًا على الندب فقط", "أنه يدل دائمًا على الإباحة", "أنه لا يدل على شيء حتى يبيّنه النبي ﷺ"], "ذهب جمهور الأصوليين من الشافعية والحنفية والمالكية والحنابلة إلى أن صيغة الأمر المجردة تفيد الوجوب بأصلها وتنتقل إلى الندب أو الإباحة أو غيرها بقرينة، وقال بعضهم إنها للندب لأنه المتيقن، وتوقف آخرون (الوقف)، والمسألة في الكتب الأصولية الكبرى."] },

  { id: "xuf-002", s: "fiqh", g: 4, d: 6, t: ["usul", "nahy", "tahrim"], tr: ["comparative", "jumhur"], src: "al-Shīrāzī, al-Lumaʿ; al-Ghazālī, al-Mustaṣfā; al-Zarkashī, al-Baḥr al-Muḥīṭ",
    en: ["What is the majority position on a prohibition (nahy) in the Sharia texts?", ["That it indicates prohibition (taḥrīm) unless an indication shifts it to disapproval (karāha) or another sense", "That it indicates only disapproval", "That it indicates nothing", "That it indicates the act is valid"], "Most uṣūlīs hold that the form of prohibition by default indicates unlawfulness, as the imperative indicates obligation by default. The debate also covers whether prohibition requires the invalidity of the act (fasād): the majority hold that a prohibition on an act in itself or its essential part indicates invalidity, while the Ḥanafīs distinguish a prohibition based on an extraneous attribute, which makes the act valid but blameworthy."],
    de: ["Was ist die Mehrheitsposition zu einem Verbot (nahy) in den Texten der Scharia?", ["Dass es Verbot (taḥrīm) anzeigt, sofern kein Hinweis es zu Missbilligung (karāha) oder anderem Sinn verschiebt", "Dass es nur Missbilligung anzeigt", "Dass es nichts anzeigt", "Dass es die Gültigkeit der Handlung anzeigt"], "Die meisten Uṣūlīs halten, dass die Verbotsform standardmäßig Unerlaubtheit anzeigt, so wie der Imperativ standardmäßig Pflicht. Die Debatte betrifft auch, ob das Verbot die Ungültigkeit (fasād) der Handlung nach sich zieht: Die Mehrheit hält, dass ein Verbot der Handlung an sich oder ihres wesentlichen Teils Ungültigkeit anzeigt, während die Ḥanafiten ein Verbot aufgrund eines äußeren Merkmals unterscheiden, das die Handlung gültig, aber tadelnswert macht."],
    ar: ["ما الموقف الراجح عند الجمهور في النهي الوارد في النصوص الشرعية؟", ["أنه يدل على التحريم ما لم تدل قرينة على الكراهة أو غيرها", "أنه يدل على الكراهة فقط", "أنه لا يدل على شيء", "أنه يدل على صحة الفعل"], "يرى أكثر الأصوليين أن صيغة النهي تفيد التحريم أصلًا كما أن الأمر يفيد الوجوب، ويتناول البحث أيضًا اقتضاء النهي فساد الفعل: فالجمهور على أن النهي عن الشيء لذاته أو لجزئه يقتضي الفساد، وفصّل الحنفية فجعلوا النهي لوصف خارج يُبقي العقد صحيحًا مع الإثم."] },

  { id: "xuf-003", s: "fiqh", g: 4, d: 7, t: ["usul", "amm-khass", "takhsis"], tr: ["hanafi", "comparative"], src: "al-Sarakhsī, Uṣūl al-Sarakhsī; al-Bazdawī, Kanz al-Wuṣūl; al-Āmidī, al-Iḥkām",
    en: ["How do the Ḥanafīs and the majority differ on a general text (ʿāmm) whose scope has been restricted?", ["The Ḥanafīs held a general text indicates its scope definitively (qaṭʿī) until restricted by a connected indication, while the majority treat it as probable (ẓannī) even before restriction", "The Ḥanafīs held a general text is always probable, and the majority held it definitive", "Both held the general text has no scope", "Both held a general text can never be restricted"], "In Ḥanafī uṣūl the ʿāmm is definitive in what it covers (like the khāṣṣ) unless it has been restricted by an independent text of equal strength which came together with it. For the majority (Shāfiʿī, Mālikī, Ḥanbalī), the ʿāmm is a probable indication because the possibility of restriction (takhṣīṣ) is always present, so a sound single-narrator report can restrict it. This accounts for several branch disagreements."],
    de: ["Wie unterscheiden sich die Ḥanafiten und die Mehrheit bei einem allgemeinen Text (ʿāmm), dessen Geltungsbereich eingeschränkt wurde?", ["Die Ḥanafiten hielten einen allgemeinen Text für sicher (qaṭʿī) in seinem Geltungsbereich, bis ihn ein verbundener Hinweis einschränkt, die Mehrheit behandelt ihn schon vor Einschränkung als wahrscheinlich (ẓannī)", "Die Ḥanafiten hielten einen allgemeinen Text immer für wahrscheinlich, die Mehrheit für sicher", "Beide hielten, der allgemeine Text habe keinen Geltungsbereich", "Beide hielten, ein allgemeiner Text könne nie eingeschränkt werden"], "In der ḥanafitischen Uṣūl ist das ʿĀmm in dem, was es umfasst, sicher (wie das Ḫāṣṣ), sofern es nicht durch einen unabhängigen Text gleicher Stärke eingeschränkt wurde, der mit ihm zusammen kam. Für die Mehrheit (Šāfiʿiten, Mālikiten, Ḥanbaliten) ist das ʿĀmm ein wahrscheinlicher Hinweis, weil die Möglichkeit der Einschränkung (taḫṣīṣ) stets besteht, sodass ein gesunder Einzelbericht es einschränken kann. Das erklärt mehrere Meinungsverschiedenheiten in Einzelfragen."],
    ar: ["كيف يختلف الحنفية والجمهور في العام الذي دخله التخصيص؟", ["الحنفية يرون العام قطعيًّا في دلالته حتى يخصصه مقارن مستقل، والجمهور يرونه ظنيًّا حتى قبل التخصيص", "الحنفية يرونه ظنيًّا دائمًا والجمهور قطعيًّا", "كلاهما يرى أن العام لا شمول له", "كلاهما يرى أن العام لا يخصّص أبدًا"], "العام عند الحنفية قطعي الدلالة على ما يشمله كالخاص ما لم يخصّصه دليل مستقل مقارن مثله في القوة، وعند الجمهور (الشافعية والمالكية والحنابلة) دلالته ظنية لأن احتمال التخصيص قائم دائمًا، فيجوز أن يخصصه خبر آحاد صحيح، وهذا أصل لكثير من الخلافات الفرعية."] },

  { id: "xuf-004", s: "fiqh", g: 4, d: 7, t: ["usul", "mutlaq-muqayyad"], tr: ["comparative", "shafii", "hanafi"], src: "al-Zarkashī, al-Baḥr al-Muḥīṭ; al-Āmidī, al-Iḥkām; al-Shīrāzī, al-Lumaʿ",
    en: ["What is the Shāfiʿī and general position when an unrestricted text (muṭlaq) and a restricted one (muqayyad) concern the same ruling and the same cause?", ["The muṭlaq is read as the muqayyad, by agreement of most", "The muqayyad is ignored", "Both are suspended", "The later text cancels the earlier one in all cases"], "When a text states a ruling without a qualification and another states the same ruling with a qualification, the scholars agree to read the unrestricted one in the light of the restricted when both the ruling and the cause are the same. When the ruling differs, they disagree: the Shāfiʿīs often carry the muṭlaq on the muqayyad through analogical common ground (as in the question of a believing slave in expiation), while the Ḥanafīs generally refuse."],
    de: ["Was ist die schāfiʿitische und allgemeine Position, wenn ein uneingeschränkter Text (muṭlaq) und ein eingeschränkter (muqayyad) dasselbe Urteil und dieselbe Ursache betreffen?", ["Das Muṭlaq wird als das Muqayyad gelesen, nach Übereinstimmung der meisten", "Das Muqayyad wird ignoriert", "Beide werden ausgesetzt", "Der spätere Text hebt den früheren in allen Fällen auf"], "Wenn ein Text ein Urteil ohne Bedingung nennt und ein anderer dasselbe Urteil mit einer Bedingung, stimmen die Gelehrten überein, den uneingeschränkten im Lichte des eingeschränkten zu lesen, sofern Urteil und Ursache gleich sind. Unterscheidet sich das Urteil, sind sie uneins: Die Šāfiʿiten übertragen das Muṭlaq oft auf das Muqayyad durch eine analogische Gemeinsamkeit (wie bei der Frage der gläubigen Sklavin bei der Sühne), während die Ḥanafiten dies im Allgemeinen ablehnen."],
    ar: ["ما الموقف الشافعي والعام حين يتعارض نص مطلق ونص مقيد في الحكم والسبب نفسيهما؟", ["يُحمل المطلق على المقيد باتفاق الأكثرين", "يُهمل المقيد", "يتوقف فيهما", "المتأخر ينسخ المتقدم دائمًا"], "إذا ورد نص بحكم مطلق ونص آخر بالحكم نفسه مقيدًا حُمل المطلق على المقيد باتفاق عند اتحاد الحكم والسبب، وإذا اختلف الحكم اختلفوا: فالشافعية كثيرًا ما يحملونه بجامع قياسي (كاشتراط الإيمان في رقبة الكفارة) والحنفية في الغالب يمنعون ذلك."] },

  { id: "xuf-005", s: "fiqh", g: 4, d: 7, t: ["usul", "mafhum-mukhalafa"], tr: ["comparative", "hanafi", "shafii"], src: "al-Āmidī, al-Iḥkām; al-Sarakhsī, Uṣūl; al-Ghazālī, al-Mustaṣfā; al-Shīrāzī, al-Lumaʿ",
    en: ["How do the schools differ on the argument from the converse meaning (mafhūm al-mukhālafa), such as a condition or description restricting a ruling?", ["The Shāfiʿīs, Mālikīs and Ḥanbalīs generally accept it for conditions and descriptions, while the Ḥanafīs generally reject it as evidence in legal texts", "All schools reject it completely", "All schools accept it for all texts without exception", "Only the Ḥanafīs accept it"], "The mafhūm al-mukhālafa infers that what is not mentioned has the opposite ruling of what is mentioned. The Shāfiʿīs, most Mālikīs and Ḥanbalīs accept it in several forms (condition, description, number), with disputes about each form and some conditions of validity. The Ḥanafīs reject it in textual rulings, though they accept the converse in the speech of the people and in some cases, and are known for refusing it."],
    de: ["Wie unterscheiden sich die Schulen beim Argument aus dem Gegenteilsinn (mafhūm al-muḫālafa), etwa wenn eine Bedingung oder Eigenschaft ein Urteil einschränkt?", ["Die Šāfiʿiten, Mālikiten und Ḥanbaliten akzeptieren es im Allgemeinen bei Bedingungen und Eigenschaften, während die Ḥanafiten es als Beleg in Rechtstexten im Allgemeinen ablehnen", "Alle Schulen lehnen es völlig ab", "Alle Schulen akzeptieren es für alle Texte ausnahmslos", "Nur die Ḥanafiten akzeptieren es"], "Der Mafhūm al-muḫālafa schließt, dass das nicht Genannte das entgegengesetzte Urteil des Genannten hat. Die Šāfiʿiten, die meisten Mālikiten und Ḥanbaliten akzeptieren ihn in mehreren Formen (Bedingung, Eigenschaft, Zahl), mit Streit über jede Form und manche Gültigkeitsbedingungen. Die Ḥanafiten lehnen ihn bei Textvorschriften ab, obwohl sie den Gegenteilsinn in der Rede der Leute und in einigen Fällen akzeptieren, und sind für die Ablehnung bekannt."],
    ar: ["كيف تختلف المذاهب في الاحتجاج بمفهوم المخالفة كتقييد الحكم بشرط أو وصف؟", ["الشافعية والمالكية والحنابلة يحتجون به عمومًا في الشرط والوصف، والحنفية في الغالب لا يحتجون به في النصوص الشرعية", "كل المذاهب ترفضه كليًّا", "كل المذاهب تقبله في كل النصوص بلا استثناء", "الحنفية وحدهم يقبلونه"], "مفهوم المخالفة أن يثبت للمسكوت عنه نقيض حكم المنطوق، ويحتج به الشافعية وأكثر المالكية والحنابلة في صور منه (الشرط والوصف والعدد) مع خلاف في كل صورة وشروط للاعتبار، ويمنع الحنفية الاحتجاج به في نصوص الأحكام وإن قبلوه في كلام الناس وفي بعض المواضع."] },

  { id: "xuf-006", s: "fiqh", g: 4, d: 7, t: ["usul", "wajib-fard"], tr: ["hanafi", "comparative"], src: "al-Sarakhsī, Uṣūl al-Sarakhsī; al-Bazdawī, Kanz al-Wuṣūl; al-Zuḥaylī, al-Wajīz fī Uṣūl al-Fiqh",
    en: ["How does the Ḥanafī school distinguish fard from wājib, in contrast to the majority?", ["Fard is an obligation established by a definitive evidence and wājib by a probable one; the majority treat both as the same category of obligation", "Fard is recommended and wājib is obligatory", "Fard is a Quranic term only for prayer", "The Ḥanafīs treat both as recommended"], "In Ḥanafī terminology, fard is established by decisive proof (a definitive Quranic text or a mutawātir report), with denial being unbelief, while wājib is established by a probable proof (a sound single-narrator report), whose denier is not considered an unbeliever though he is sinful for neglecting it. The majority consider them synonyms. The Ḥanafī distinction yields branch consequences, for instance regarding the Witr prayer and the rites of ḥajj."],
    de: ["Wie unterscheidet die ḥanafitische Schule fard von wāǧib im Gegensatz zur Mehrheit?", ["Fard ist eine durch sicheren Beleg begründete Pflicht und wāǧib eine durch wahrscheinlichen Beleg begründete; die Mehrheit behandelt beide als dieselbe Kategorie der Pflicht", "Fard ist empfohlen und wāǧib verpflichtend", "Fard ist ein koranischer Begriff nur für das Gebet", "Die Ḥanafiten behandeln beide als empfohlen"], "In der ḥanafitischen Terminologie wird Fard durch entscheidenden Beleg (einen sicheren Korantext oder einen mutawātir-Bericht) begründet, und seine Leugnung ist Unglaube, während Wāǧib durch einen wahrscheinlichen Beleg (einen gesunden Einzelbericht) begründet wird, dessen Leugner nicht als Ungläubiger gilt, aber bei Vernachlässigung sündigt. Die Mehrheit hält beide für Synonyme. Die ḥanafitische Unterscheidung hat Folgen in Einzelfragen, etwa beim Witr-Gebet und den Riten des Ḥaǧǧ."],
    ar: ["كيف يفرّق الحنفية بين الفرض والواجب خلافًا للجمهور؟", ["الفرض ما ثبت بدليل قطعي والواجب ما ثبت بدليل ظني، والجمهور يجعلونهما مترادفين", "الفرض مندوب والواجب لازم", "الفرض لفظ قرآني للصلاة فقط", "الحنفية يجعلونهما مندوبين"], "الفرض عند الحنفية ما ثبت بدليل قطعي (نص قرآني قطعي أو خبر متواتر) ويكفر جاحده، والواجب ما ثبت بدليل ظني (خبر آحاد صحيح) ولا يكفر جاحده وإن أثم تاركه، والجمهور يعدونهما مترادفين، وللتفريق أثر في فروع كالوتر ومناسك الحج."] },

  { id: "xuf-007", s: "fiqh", g: 4, d: 6, t: ["usul", "qiyas", "arkan"], tr: ["jumhur"], src: "al-Ghazālī, al-Mustaṣfā; al-Shīrāzī, al-Lumaʿ; al-Āmidī, al-Iḥkām",
    en: ["Which four pillars (arkān) of qiyās do the uṣūlīs state?", ["The original case (aṣl), the new case (farʿ), the ruling of the original (ḥukm al-aṣl) and the effective cause (ʿilla)", "The text, the consensus, the custom and the benefit", "The caliph, the judge, the witness and the oath", "The question, the answer, the proof and the objection"], "The majority list four pillars: the aṣl (the case with a text or consensus), the farʿ (the case without a text), the ḥukm al-aṣl and the ʿilla that connects them. Some, such as the Ḥanafī Abū Zayd al-Dabūsī, speak of the aṣl as the text while others treat the ruling of the aṣl as separate. The ʿilla is the pivotal topic, with rules for how it is discovered (masālik al-ʿilla)."],
    de: ["Welche vier Säulen (arkān) des Qiyās nennen die Uṣūlīs?", ["Der Ausgangsfall (aṣl), der neue Fall (farʿ), das Urteil des Ausgangsfalls (ḥukm al-aṣl) und die wirksame Ursache (ʿilla)", "Der Text, der Konsens, der Brauch und der Nutzen", "Der Kalif, der Richter, der Zeuge und der Eid", "Die Frage, die Antwort, der Beweis und der Einwand"], "Die Mehrheit nennt vier Säulen: den Aṣl (den Fall mit Text oder Konsens), den Farʿ (den Fall ohne Text), den Ḥukm al-aṣl und die ʿIlla, die sie verbindet. Manche wie der Ḥanafit Abū Zaid ad-Dabūsī sprechen vom Aṣl als dem Text, andere behandeln das Urteil des Aṣl gesondert. Die ʿIlla ist das zentrale Thema, mit Regeln, wie sie gefunden wird (masālik al-ʿilla)."],
    ar: ["ما الأركان الأربعة للقياس عند الأصوليين؟", ["الأصل والفرع وحكم الأصل والعلة", "النص والإجماع والعرف والمصلحة", "الخليفة والقاضي والشاهد واليمين", "السؤال والجواب والدليل والاعتراض"], "عدّ الجمهور أركان القياس أربعة: الأصل (المحل المنصوص عليه أو المجمع عليه) والفرع (المحل غير المنصوص) وحكم الأصل والعلة الجامعة، وجعل بعضهم كأبي زيد الدبوسي الأصل هو النص وفصل آخرون حكم الأصل، والعلة محور الباب ولها مسالك لإثباتها."] },

  { id: "xuf-008", s: "fiqh", g: 4, d: 7, t: ["usul", "qiyas", "illa", "masalik"], tr: ["comparative"], src: "al-Ghazālī, Shifāʾ al-Ghalīl; al-Zarkashī, al-Baḥr al-Muḥīṭ; Ibn Qudāma, Rawḍat al-Nāẓir",
    en: ["Which list names classical ways of establishing the effective cause (masālik al-ʿilla)?", ["Text, consensus, inference by suitability (munāsaba), sorting and elimination (sabr wa-taqsīm), concomitance (dawarān) and fitness for the ruling", "Dreams, lots, geography, tribal custom and age", "The preference of the judge, the market price, the opinion of the physician and the calendar", "Analogy to poetry, the length of the verse, rhyme and metre"], "Uṣūlīs list ways to find the ʿilla: by text (naṣṣ) or indication (īmāʾ), consensus, munāsaba (suitability), sabr wa-taqsīm (examining and eliminating the possible causes), dawarān (the ruling goes with the cause present or absent), shabah and others. Their order and acceptance differ, with al-Ghazālī and Ibn Qudāma giving detailed accounts."],
    de: ["Welche Liste nennt klassische Wege zur Feststellung der wirksamen Ursache (masālik al-ʿilla)?", ["Text, Konsens, Schluss aus Eignung (munāsaba), Sortieren und Ausschließen (sabr wa-taqsīm), Mitlauf (dawarān) und Eignung für das Urteil", "Träume, Lose, Geografie, Stammesbrauch und Alter", "Die Vorliebe des Richters, der Marktpreis, die Meinung des Arztes und der Kalender", "Analogie zur Dichtung, Länge des Verses, Reim und Metrum"], "Die Uṣūlīs nennen Wege zur Auffindung der ʿIlla: durch Text (naṣṣ) oder Hinweis (īmāʾ), Konsens, Munāsaba (Eignung), Sabr wa-taqsīm (Prüfen und Ausschließen der möglichen Ursachen), Dawarān (das Urteil folgt der Ursache in Anwesenheit und Abwesenheit), Šabah und andere. Reihenfolge und Anerkennung unterscheiden sich, wobei al-Ġazālī und Ibn Qudāma ausführliche Darstellungen geben."],
    ar: ["أي قائمة تذكر مسالك العلة الكلاسيكية؟", ["النص والإجماع والمناسبة والسبر والتقسيم والدوران والشبه", "الأحلام والقرعة والجغرافيا والعرف القبلي والعمر", "رأي القاضي وسعر السوق وقول الطبيب والتقويم", "القياس على الشعر وطول البيت والقافية والوزن"], "يعدّ الأصوليون مسالك العلة: النص والإيماء والإجماع والمناسبة والسبر والتقسيم والدوران والشبه وغيرها، ويختلفون في ترتيبها وقبولها، وقد فصّل الغزالي وابن قدامة الكلام فيها."] },

  { id: "xuf-009", s: "fiqh", g: 4, d: 7, t: ["usul", "istihsan"], tr: ["hanafi", "maliki", "shafii", "comparative"], src: "al-Shāfiʿī, al-Umm and al-Risāla (Ibṭāl al-Istiḥsān); al-Sarakhsī, al-Mabsūṭ; al-Shāṭibī, al-Muwāfaqāt",
    en: ["How did the schools treat istiḥsān (juristic preference) as an argument?", ["The Ḥanafīs and Mālikīs used it as a recognised method while al-Shāfiʿī rejected it in the sense of legislating by one’s own taste; later Ḥanbalīs accepted forms of it grounded in texts", "All the schools rejected it entirely", "All the schools accepted it without conditions", "Only the Shāfiʿīs accepted it"], "Al-Shāfiʿī wrote a chapter on the invalidation of istiḥsān, saying that whoever prefers by taste has legislated. The Ḥanafīs define it as leaving an apparent analogy for a stronger one or for a text, consensus, necessity or custom, and the Mālikīs similarly speak of it as preferring the best of two evidences. Later uṣūlīs observed that the schools differ more in the definition than in practice."],
    de: ["Wie behandelten die Schulen Istiḥsān (juristische Bevorzugung) als Argument?", ["Ḥanafiten und Mālikiten wandten es als anerkannte Methode an, während aš-Šāfiʿī es ablehnte, wenn man nach eigenem Geschmack Recht setzt; spätere Ḥanbaliten akzeptierten in Texten gegründete Formen", "Alle Schulen lehnten es ganz ab", "Alle Schulen akzeptierten es ohne Bedingungen", "Nur die Šāfiʿiten akzeptierten es"], "Aš-Šāfiʿī schrieb ein Kapitel über die Aufhebung des Istiḥsān und sagte, wer nach Geschmack bevorzuge, habe Recht gesetzt. Die Ḥanafiten definieren es als Verlassen eines naheliegenden Analogieschlusses für einen stärkeren oder für einen Text, Konsens, Notwendigkeit oder Brauch, und die Mālikiten sprechen ähnlich von der Bevorzugung des besseren zweier Belege. Spätere Uṣūlīs bemerkten, dass die Schulen sich mehr in der Definition als in der Praxis unterscheiden."],
    ar: ["كيف تعاملت المذاهب مع الاستحسان دليلًا؟", ["احتج به الحنفية والمالكية منهجًا معتبرًا ورده الشافعي بمعنى التشريع بالتشهي، وقبل متأخرو الحنابلة صورًا منه مبنية على النصوص", "ردته المذاهب كلها كليًّا", "قبلته المذاهب كلها بلا شروط", "قبله الشافعية وحدهم"], "ألّف الشافعي بابًا في إبطال الاستحسان وقال إن من استحسن فقد شرّع، وعرّفه الحنفية بأنه العدول عن قياس ظاهر إلى أقوى منه أو إلى نص أو إجماع أو ضرورة أو عرف، وتكلم المالكية بنحوه بتقديم أحسن الدليلين، وقد لاحظ متأخرو الأصوليين أن الخلاف في الاسم أكثر منه في العمل."] },

  { id: "xuf-010", s: "fiqh", g: 4, d: 6, t: ["usul", "maslaha-mursala"], tr: ["maliki", "hanbali", "shafii", "comparative"], src: "al-Shāṭibī, al-Iʿtiṣām and al-Muwāfaqāt; al-Ghazālī, al-Mustaṣfā; al-Qarāfī, Sharḥ Tanqīḥ al-Fuṣūl",
    en: ["Which school is most closely associated with relying on unrestricted public interest (al-maṣlaḥa al-mursala), and how did al-Ghazālī treat it?", ["The Mālikī school; al-Ghazālī accepted it only if it is essential, universal and certain (ḍarūrī, kullī, qaṭʿī)", "The Ḥanafī school only; al-Ghazālī rejected it entirely", "The Shāfiʿī school only; al-Ghazālī accepted all interests", "No school; it was invented in the 20th century"], "Mālik and his school are associated with maṣāliḥ mursala, interests not specifically endorsed or rejected by a text. Al-Ghazālī in al-Mustaṣfā treated it with conditions: the interest must belong to the necessities (protection of religion, life, intellect, lineage and property), be general for the community and be certain. The Ḥanbalīs, especially al-Ṭūfī, discussed it extensively, and al-Shāṭibī built the theory in al-Iʿtiṣām."],
    de: ["Welche Schule ist am engsten mit der Berufung auf unbeschränktes Gemeinwohl (al-maṣlaḥa al-mursala) verbunden, und wie behandelte es al-Ġazālī?", ["Die mālikitische Schule; al-Ġazālī akzeptierte es nur, wenn es wesentlich, allgemein und sicher ist (ḍarūrī, kullī, qaṭʿī)", "Nur die ḥanafitische Schule; al-Ġazālī lehnte es ganz ab", "Nur die šāfiʿitische Schule; al-Ġazālī akzeptierte alle Interessen", "Keine Schule; es wurde im 20. Jahrhundert erfunden"], "Mālik und seine Schule werden mit den Maṣāliḥ mursala verbunden, Interessen, die ein Text weder ausdrücklich bestätigt noch verwirft. Al-Ġazālī behandelte es in al-Mustaṣfā mit Bedingungen: Das Interesse muss zu den Notwendigkeiten gehören (Schutz von Religion, Leben, Verstand, Abstammung und Besitz), für die Gemeinschaft allgemein sein und sicher. Die Ḥanbaliten, besonders aṭ-Ṭūfī, erörterten es ausführlich, und aš-Šāṭibī baute die Theorie in al-Iʿtiṣām aus."],
    ar: ["أي مذهب ارتبط أكثر بالاحتجاج بالمصلحة المرسلة وكيف عاملها الغزالي؟", ["المذهب المالكي، وقبلها الغزالي بشرط أن تكون ضرورية كلية قطعية", "المذهب الحنفي وحده، ورفضها الغزالي كليًّا", "المذهب الشافعي وحده، وقبل الغزالي كل المصالح", "لا مذهب، فهي من اختراع القرن العشرين"], "ارتبطت المصالح المرسلة (التي لم يشهد لها نص بالاعتبار أو الإلغاء) بمالك ومذهبه، وعالجها الغزالي في «المستصفى» بشروط: أن تكون من الضروريات (حفظ الدين والنفس والعقل والنسل والمال) وكلية للأمة وقطعية، وتوسع فيها الحنابلة وخاصة الطوفي، وبنى الشاطبي نظريتها في «الاعتصام»."] },

  { id: "xuf-011", s: "fiqh", g: 4, d: 7, t: ["usul", "amal-ahl-madina"], tr: ["maliki", "comparative"], src: "al-Qāḍī ʿIyāḍ, Tartīb al-Madārik; Ibn Taymiyya, Majmūʿ al-Fatāwā, on ʿamal ahl al-Madīna; Ibn al-Qayyim, Iʿlām al-Muwaqqiʿīn",
    en: ["What is the Mālikī doctrine of the practice of the people of Madīna (ʿamal ahl al-Madīna), and how did the other schools react?", ["Mālikīs treated the established practice of Madīna as evidence, strongest when it is transmitted from generation to generation; the Shāfiʿīs and most Ḥanbalīs did not take it as independent proof, and Ibn Taymiyya distinguished degrees of it", "All schools accepted it identically", "The Ḥanafīs made it equal to the Quran", "It was a rule that all prayers must be in Madīna"], "Mālik gave weight to the inherited practice of Madīna, especially where it transmits the Prophetic practice (such as the measure of the ṣāʿ and the call to prayer), considering it stronger than a single-narrator report. Al-Shāfiʿī and others held that the evidence is the text, not the practice, and Ibn Taymiyya in his writings distinguished practice that transmits the sunna from practice based on later ijtihād. Opinions within the Mālikī school also vary."],
    de: ["Was ist die mālikitische Lehre von der Praxis der Leute von Medina (ʿamal ahl al-Madīna), und wie reagierten die anderen Schulen?", ["Die Mālikiten behandelten die feststehende Praxis Medinas als Beleg, am stärksten, wenn sie von Generation zu Generation überliefert ist; die Šāfiʿiten und die meisten Ḥanbaliten nahmen sie nicht als eigenständigen Beweis, und Ibn Taimiyya unterschied Stufen davon", "Alle Schulen akzeptierten sie gleich", "Die Ḥanafiten stellten sie dem Koran gleich", "Es war eine Regel, dass alle Gebete in Medina stattfinden müssen"], "Mālik gab der ererbten Praxis Medinas Gewicht, besonders wo sie die prophetische Praxis überliefert (wie das Maß des Ṣāʿ und der Gebetsruf), und hielt sie für stärker als einen Einzelbericht. Aš-Šāfiʿī und andere hielten, der Beleg sei der Text, nicht die Praxis, und Ibn Taimiyya unterschied in seinen Schriften Praxis, die die Sunna überliefert, von Praxis auf Grundlage späteren Iǧtihāds. Auch innerhalb der mālikitischen Schule gehen die Meinungen auseinander."],
    ar: ["ما مذهب المالكية في عمل أهل المدينة وكيف تعامل معه غيرهم؟", ["اعتبره المالكية حجة وأقواها ما نُقل نقلًا متواترًا جيلًا عن جيل، ولم يجعله الشافعية وأكثر الحنابلة دليلًا مستقلًّا، وفصّل ابن تيمية في مراتبه", "قبلته المذاهب كلها بالدرجة نفسها", "جعله الحنفية مساويًا للقرآن", "هو قاعدة بوجوب أداء الصلوات كلها في المدينة"], "أعطى مالك وزنًا لعمل أهل المدينة المتوارث لا سيما فيما ينقل السنة العملية كمقدار الصاع والأذان، وقدمه على خبر الآحاد، وقال الشافعي وغيره إن الحجة في النص لا في العمل، وفصل ابن تيمية بين عمل ينقل السنة وعمل مبني على اجتهاد متأخر، وللمالكية أنفسهم أقوال في ذلك."] },

  { id: "xuf-012", s: "fiqh", g: 4, d: 6, t: ["usul", "sadd-dhara-i"], tr: ["maliki", "hanbali", "comparative"], src: "al-Qarāfī, al-Furūq; Ibn al-Qayyim, Iʿlām al-Muwaqqiʿīn; al-Shāṭibī, al-Muwāfaqāt",
    en: ["What is sadd al-dharāʾiʿ (blocking the means) and which schools use it prominently?", ["Prohibiting a lawful act when it leads, in most cases, to a forbidden one; the Mālikīs and Ḥanbalīs use it prominently, and Ibn al-Qayyim wrote extensively on it", "Closing the doors of mosques at night", "Permitting an unlawful act by necessity", "A prayer performed on a ship"], "Dharāʾiʿ are the means leading to an end; if the end is forbidden and the means usually lead to it, the means are prohibited. The Mālikīs, with al-Qarāfī’s classification, and the Ḥanbalīs apply it prominently, while the Ḥanafīs and Shāfiʿīs apply it in some cases without making it a distinct proof. Ibn al-Qayyim lists ninety-nine proofs for it in Iʿlām al-Muwaqqiʿīn."],
    de: ["Was ist Sadd aḏ-ḏarāʾiʿ (Sperren der Wege), und welche Schulen wenden es prominent an?", ["Das Verbot einer erlaubten Handlung, wenn sie meist zu einer verbotenen führt; Mālikiten und Ḥanbaliten wenden es prominent an, und Ibn al-Qayyim schrieb ausführlich darüber", "Das Schließen der Moscheetüren bei Nacht", "Das Erlauben einer unerlaubten Handlung aus Not", "Ein auf einem Schiff verrichtetes Gebet"], "Ḏarāʾiʿ sind die Mittel, die zu einem Ziel führen; ist das Ziel verboten und führen die Mittel meist dorthin, sind die Mittel verboten. Die Mālikiten mit al-Qarāfīs Einteilung und die Ḥanbaliten wenden es prominent an, während Ḥanafiten und Šāfiʿiten es in manchen Fällen anwenden, ohne es zu einem eigenen Beleg zu machen. Ibn al-Qayyim führt in Iʿlām al-Muwaqqiʿīn viele Belege dafür an."],
    ar: ["ما سد الذرائع وأي المذاهب تعتمده بصورة بارزة؟", ["منع فعل مباح إذا كان يفضي غالبًا إلى محرم، ويعتمده المالكية والحنابلة بصورة بارزة وأطال فيه ابن القيم", "إغلاق أبواب المساجد ليلًا", "إباحة فعل محرم للضرورة", "صلاة تؤدى على السفينة"], "الذرائع هي الوسائل المفضية إلى مقصد، فإذا كان المقصد محرمًا وكانت الوسيلة تفضي إليه غالبًا مُنعت، ويعمل به المالكية (وقد قسّمه القرافي) والحنابلة عملًا بارزًا، ويعمل به الحنفية والشافعية في بعض المسائل دون جعله دليلًا مستقلًّا، وأفاض ابن القيم في أدلته في «إعلام الموقعين»."] },

  { id: "xuf-013", s: "fiqh", g: 4, d: 6, t: ["usul", "ijma"], tr: ["jumhur", "comparative"], src: "al-Shāfiʿī, al-Risāla; al-Ghazālī, al-Mustaṣfā; al-Shīrāzī, al-Lumaʿ; Ibn Qudāma, Rawḍat al-Nāẓir",
    en: ["How do the schools define ijmāʿ, and who held that only the consensus of the Companions counts?", ["Agreement of the mujtahids of the Muslim community of an age on a legal ruling after the Prophet; Dāwūd al-Ẓāhirī and, in one report, Aḥmad limited it to the Companions", "Agreement of the rulers of the community on taxes; the Ḥanafīs limited it", "Agreement of ordinary Muslims on custom; the Mālikīs limited it", "Agreement of the poets of an age; the Shāfiʿīs limited it"], "The majority define ijmāʿ as the agreement of all mujtahids of the Muslim community after the Prophet in a given period on a legal ruling. The Ẓāhirīs (Dāwūd and Ibn Ḥazm) limited it to the Companions, and a report from Aḥmad leans the same way. Mālikīs also speak of the consensus of the people of Madīna, and the Shīʿa have their own conception based on the imām."],
    de: ["Wie definieren die Schulen Iǧmāʿ, und wer hielt, dass nur der Konsens der Gefährten zählt?", ["Übereinstimmung der Mudschtahids der muslimischen Gemeinschaft eines Zeitalters über ein Rechtsurteil nach dem Propheten; Dāwūd aẓ-Ẓāhirī und nach einem Bericht Aḥmad beschränkten ihn auf die Gefährten", "Übereinstimmung der Herrscher der Gemeinschaft über Steuern; die Ḥanafiten beschränkten ihn", "Übereinstimmung gewöhnlicher Muslime über Brauch; die Mālikiten beschränkten ihn", "Übereinstimmung der Dichter eines Zeitalters; die Šāfiʿiten beschränkten ihn"], "Die Mehrheit definiert Iǧmāʿ als die Übereinstimmung aller Mudschtahids der muslimischen Gemeinschaft nach dem Propheten in einem Zeitraum über ein Rechtsurteil. Die Ẓāhiriten (Dāwūd und Ibn Ḥazm) beschränkten ihn auf die Gefährten, und ein Bericht von Aḥmad neigt ebenso. Auch Mālikiten sprechen vom Konsens der Leute von Medina, und die Schia hat eine eigene Vorstellung auf Grundlage des Imams."],
    ar: ["كيف تعرّف المذاهب الإجماع ومن قصره على إجماع الصحابة؟", ["اتفاق مجتهدي الأمة في عصر على حكم شرعي بعد النبي ﷺ، وقصره داود الظاهري وفي رواية أحمد على الصحابة", "اتفاق حكام الأمة على الضرائب، وقصره الحنفية", "اتفاق عامة المسلمين على العرف، وقصره المالكية", "اتفاق شعراء العصر، وقصره الشافعية"], "عرّف الجمهور الإجماع بأنه اتفاق جميع مجتهدي الأمة بعد النبي ﷺ في عصر على حكم شرعي، وقصره الظاهرية (داود وابن حزم) على الصحابة ويُروى عن أحمد ما يميل إليه، ويتحدث المالكية أيضًا عن إجماع أهل المدينة، وللشيعة تصور خاص مبني على الإمام."] },

  { id: "xuf-014", s: "fiqh", g: 4, d: 7, t: ["usul", "ijma", "sukuti"], tr: ["comparative", "hanafi", "shafii"], src: "al-Āmidī, al-Iḥkām; al-Ghazālī, al-Mustaṣfā; al-Sarakhsī, Uṣūl",
    en: ["What is the tacit consensus (al-ijmāʿ al-sukūtī), and how do the schools judge it?", ["When some mujtahids state a ruling and the others know of it and stay silent without objection; the Ḥanafīs and many Ḥanbalīs treat it as proof, while al-Shāfiʿī and many Shāfiʿīs do not", "When all mujtahids sign a document", "When the ruler imposes silence", "When the Quran is recited silently"], "The ijmāʿ sukūtī occurs when a ruling is expressed by some of the mujtahids of an age and the rest, who know of it, remain silent with no sign of approval or disapproval. The Ḥanafīs and some Ḥanbalīs accept it as proof (some as conclusive, some as probable), but al-Shāfiʿī and many of his followers deny that silence indicates agreement. Al-Āmidī and al-Ghazālī lay out the positions."],
    de: ["Was ist der stillschweigende Konsens (al-iǧmāʿ as-sukūtī), und wie beurteilen ihn die Schulen?", ["Wenn einige Mudschtahids ein Urteil aussprechen und die anderen, die davon wissen, ohne Einwand schweigen; die Ḥanafiten und viele Ḥanbaliten behandeln ihn als Beleg, aš-Šāfiʿī und viele Šāfiʿiten nicht", "Wenn alle Mudschtahids ein Dokument unterzeichnen", "Wenn der Herrscher Schweigen auferlegt", "Wenn der Koran leise rezitiert wird"], "Der Iǧmāʿ sukūtī liegt vor, wenn ein Urteil von einigen Mudschtahids eines Zeitalters geäußert wird und die übrigen, die davon wissen, schweigen, ohne Zeichen von Zustimmung oder Ablehnung. Die Ḥanafiten und manche Ḥanbaliten akzeptieren ihn als Beleg (manche als sicher, manche als wahrscheinlich), doch aš-Šāfiʿī und viele seiner Anhänger bestreiten, dass Schweigen Zustimmung anzeigt. Al-Āmidī und al-Ġazālī stellen die Positionen dar."],
    ar: ["ما الإجماع السكوتي وكيف تحكم عليه المذاهب؟", ["أن يقول بعض المجتهدين حكمًا ويعلم به الباقون فيسكتون دون إنكار، ويحتج به الحنفية وكثير من الحنابلة، ولا يحتج به الشافعي وكثير من الشافعية", "أن يوقّع المجتهدون كلهم على وثيقة", "أن يفرض الحاكم الصمت", "أن يُقرأ القرآن سرًّا"], "الإجماع السكوتي أن يصرّح بعض مجتهدي العصر بحكم ويعلم به الباقون فيسكتون بلا رضا ظاهر ولا إنكار، وقبله الحنفية وبعض الحنابلة حجة (قطعية عند بعضهم وظنية عند آخرين)، وأنكر الشافعي وكثير من أصحابه دلالة السكوت على الموافقة، وقد عرض الآمدي والغزالي الأقوال."] },

  { id: "xuf-015", s: "fiqh", g: 4, d: 6, t: ["usul", "sahabi-qawl"], tr: ["hanafi", "maliki", "hanbali", "shafii", "comparative"], src: "al-Shāfiʿī, al-Risāla; Ibn al-Qayyim, Iʿlām al-Muwaqqiʿīn, on the opinion of the Companion; al-Āmidī, al-Iḥkām",
    en: ["How do the schools treat the opinion of a single Companion (qawl al-ṣaḥābī) as an argument?", ["The Ḥanafīs, Mālikīs and Ḥanbalīs generally treat it as evidence in some conditions, while the later position of al-Shāfiʿī and most Shāfiʿīs did not take it as binding proof", "All schools reject it entirely", "All schools treat it as equal to the Quran", "Only the Shāfiʿīs accept it"], "A Companion’s opinion where there is no known disagreement and which cannot be a matter of ijtihād is widely treated as carrying the weight of a Prophetic report. For other cases, the Ḥanafīs generally prefer it to analogy, the Mālikīs and Ḥanbalīs use it widely (Ibn al-Qayyim gives a long defence), and in his later view al-Shāfiʿī did not consider it binding, with reports of both views in his writings."],
    de: ["Wie behandeln die Schulen die Meinung eines einzelnen Gefährten (qaul aṣ-ṣaḥābī) als Argument?", ["Ḥanafiten, Mālikiten und Ḥanbaliten behandeln sie im Allgemeinen unter Bedingungen als Beleg, während die spätere Position aš-Šāfiʿīs und der meisten Šāfiʿiten sie nicht als bindenden Beweis nahm", "Alle Schulen lehnen sie ganz ab", "Alle Schulen stellen sie dem Koran gleich", "Nur die Šāfiʿiten akzeptieren sie"], "Die Meinung eines Gefährten, bei der keine Meinungsverschiedenheit bekannt ist und die nicht Sache des Iǧtihād sein kann, trägt weithin das Gewicht eines prophetischen Berichts. In anderen Fällen ziehen die Ḥanafiten sie im Allgemeinen dem Analogieschluss vor, die Mālikiten und Ḥanbaliten gebrauchen sie breit (Ibn al-Qayyim gibt eine lange Verteidigung), und nach seiner späteren Ansicht hielt aš-Šāfiʿī sie nicht für bindend, wobei in seinen Schriften beide Ansichten berichtet werden."],
    ar: ["كيف تعامل المذاهب قول الصحابي الواحد دليلًا؟", ["يحتج به الحنفية والمالكية والحنابلة عمومًا بشروط، ولم يعتبره الشافعي في قوله المتأخر وأكثر الشافعية حجة ملزمة", "ترفضه المذاهب كلها كليًّا", "تجعله المذاهب كلها مساويًا للقرآن", "يقبله الشافعية وحدهم"], "قول الصحابي الذي لا يُعرف له مخالف ولا مجال للرأي فيه يحمله كثيرون على الرفع، وفي غير ذلك يقدمه الحنفية عمومًا على القياس ويكثر المالكية والحنابلة من الاحتجاج به (ودافع عنه ابن القيم دفاعًا مطولًا)، ولم يره الشافعي في قوله المتأخر ملزمًا، وفي كتبه روايتان."] },

  { id: "xuf-016", s: "fiqh", g: 4, d: 7, t: ["usul", "shar-man-qablana"], tr: ["hanafi", "maliki", "shafii", "hanbali", "comparative"], src: "al-Āmidī, al-Iḥkām; al-Zarkashī, al-Baḥr al-Muḥīṭ; al-Zuḥaylī, Uṣūl al-Fiqh al-Islāmī",
    en: ["What is the question of 'the law of those before us' (sharʿ man qablanā), and what do the schools hold?", ["Whether laws of earlier prophets, reported in the Quran or sound Sunna without abrogation, bind us; most Ḥanafīs, many Mālikīs and Ḥanbalīs hold that they do, while the majority of Shāfiʿīs in the dominant view and Ashʿarīs hold they do not unless confirmed", "Whether previous nations had prayer; all agree", "Whether we may read their scriptures in prayer; all agree", "Whether Christians may enter mosques"], "The question concerns rulings narrated in our sources from earlier prophets without being confirmed or abrogated in our Sharia. The Ḥanafīs, many Mālikīs and Ḥanbalīs hold they bind us, as in the case of retaliation (qiṣāṣ) in some applications. Many Shāfiʿīs and Ashʿarīs say they do not bind unless our Sharia confirms them. Agreed is that what our Sharia abrogates does not bind."],
    de: ["Was ist die Frage vom ‚Gesetz derer vor uns‘ (šarʿ man qablanā), und was halten die Schulen?", ["Ob in Koran oder gesunder Sunna berichtete, nicht aufgehobene Gesetze früherer Propheten uns binden; die meisten Ḥanafiten, viele Mālikiten und Ḥanbaliten bejahen es, während die Mehrheit der Šāfiʿiten in der vorherrschenden Ansicht und die Ašʿariten es verneinen, sofern es nicht bestätigt wird", "Ob frühere Völker das Gebet hatten; alle sind sich einig", "Ob wir ihre Schriften im Gebet lesen dürfen; alle sind sich einig", "Ob Christen Moscheen betreten dürfen"], "Die Frage betrifft Vorschriften, die unsere Quellen von früheren Propheten berichten, ohne dass sie in unserer Scharia bestätigt oder aufgehoben werden. Die Ḥanafiten, viele Mālikiten und Ḥanbaliten halten, dass sie uns binden, wie bei der Vergeltung (qiṣāṣ) in manchen Anwendungen. Viele Šāfiʿiten und Ašʿariten sagen, sie binden nicht, es sei denn, unsere Scharia bestätigt sie. Einig ist man, dass das, was unsere Scharia aufhebt, nicht bindet."],
    ar: ["ما مسألة «شرع من قبلنا» وماذا تقول المذاهب فيها؟", ["هل تلزمنا شرائع الأنبياء السابقين المحكية في القرآن أو السنة الصحيحة دون نسخ؟ قال أكثر الحنفية وكثير من المالكية والحنابلة نعم، والأكثر من الشافعية في الأرجح والأشاعرة لا ما لم يقرها شرعنا", "هل كان للأمم السابقة صلاة؟ اتفاق", "هل نقرأ كتبهم في الصلاة؟ اتفاق", "هل يدخل النصارى المساجد؟"], "تتعلق المسألة بأحكام تنقلها مصادرنا عن أنبياء سابقين دون إقرار أو نسخ في شريعتنا، فيرى الحنفية وكثير من المالكية والحنابلة أنها تلزمنا كما في القصاص في بعض تطبيقاته، ويقول كثير من الشافعية والأشاعرة إنها لا تلزم إلا إذا أقرها شرعنا، ومتفق على أن ما نسخه شرعنا لا يلزم."] },

  { id: "xuf-017", s: "fiqh", g: 4, d: 6, t: ["usul", "sources", "agreed-disputed"], tr: ["jumhur"], src: "Ibn Qudāma, Rawḍat al-Nāẓir; al-Ghazālī, al-Mustaṣfā; al-Zuḥaylī, al-Wajīz fī Uṣūl al-Fiqh",
    en: ["Which list names the four sources of law agreed upon by the Sunni majority, in the usual order?", ["The Quran, the Sunna, ijmāʿ and qiyās", "The Quran, custom, reason and poetry", "The Sunna, qiyās, istiḥsān and dreams", "The Quran, the preference of the caliph, ijmāʿ and the market"], "The four agreed sources are the Quran, the Sunna, ijmāʿ and qiyās (with the Ẓāhirīs rejecting qiyās). The disputed sources include istiḥsān, maṣlaḥa mursala, istiṣḥāb, ʿurf, sadd al-dharāʾiʿ, qawl al-ṣaḥābī and sharʿ man qablanā. The Ibn Qudāma and al-Ghazālī manuals treat the sources in this arrangement."],
    de: ["Welche Liste nennt die vier von der sunnitischen Mehrheit anerkannten Rechtsquellen in der üblichen Reihenfolge?", ["Der Koran, die Sunna, Iǧmāʿ und Qiyās", "Der Koran, Brauch, Verstand und Dichtung", "Die Sunna, Qiyās, Istiḥsān und Träume", "Der Koran, die Vorliebe des Kalifen, Iǧmāʿ und der Markt"], "Die vier anerkannten Quellen sind Koran, Sunna, Iǧmāʿ und Qiyās (wobei die Ẓāhiriten den Qiyās ablehnen). Zu den umstrittenen Quellen gehören Istiḥsān, Maṣlaḥa mursala, Istiṣḥāb, ʿUrf, Sadd aḏ-ḏarāʾiʿ, Qaul aṣ-ṣaḥābī und Šarʿ man qablanā. Die Handbücher von Ibn Qudāma und al-Ġazālī behandeln die Quellen in dieser Anordnung."],
    ar: ["أي قائمة تذكر مصادر التشريع الأربعة المتفق عليها عند جمهور أهل السنة بالترتيب المعتاد؟", ["القرآن والسنة والإجماع والقياس", "القرآن والعرف والعقل والشعر", "السنة والقياس والاستحسان والأحلام", "القرآن ورأي الخليفة والإجماع والسوق"], "الأدلة المتفق عليها القرآن والسنة والإجماع والقياس (وأنكر الظاهرية القياس)، والمختلف فيها الاستحسان والمصلحة المرسلة والاستصحاب والعرف وسد الذرائع وقول الصحابي وشرع من قبلنا، وعلى هذا الترتيب جرى ابن قدامة والغزالي."] },

  { id: "xuf-018", s: "fiqh", g: 4, d: 7, t: ["usul", "zahiri", "ibn-hazm"], tr: ["comparative"], src: "Ibn Ḥazm, al-Iḥkām fī Uṣūl al-Aḥkām; Ibn Ḥazm, al-Muḥallā",
    en: ["What was Ibn Ḥazm’s approach to legal reasoning in al-Iḥkām?", ["He rejected qiyās, istiḥsān and taqlīd and held to the apparent meaning of the texts and consensus of the Companions", "He accepted all analogies without text", "He relied on custom alone", "He rejected the Sunna as a source"], "The Ẓāhirī school, founded by Dāwūd al-Ẓāhirī and defended by Ibn Ḥazm (d. 456 AH) in al-Iḥkām fī Uṣūl al-Aḥkām and al-Muḥallā, held to the plain meaning of the Quran and Sunna, and denied that analogy, juristic preference and blind following are valid sources. It limited consensus to that of the Companions. His work is argued in a polemic style against the other schools."],
    de: ["Was war Ibn Ḥazms Ansatz zur Rechtsfindung in al-Iḥkām?", ["Er lehnte Qiyās, Istiḥsān und Taqlīd ab und hielt am offenkundigen Sinn der Texte und am Konsens der Gefährten fest", "Er akzeptierte alle Analogien ohne Text", "Er stützte sich allein auf Brauch", "Er lehnte die Sunna als Quelle ab"], "Die ẓāhiritische Schule, begründet von Dāwūd aẓ-Ẓāhirī und verteidigt von Ibn Ḥazm (gest. 456 n. H.) in al-Iḥkām fī Uṣūl al-Aḥkām und al-Muḥallā, hielt am offenkundigen Sinn von Koran und Sunna fest und bestritt, dass Analogie, juristische Bevorzugung und blindes Nachfolgen gültige Quellen sind. Den Konsens beschränkte sie auf den der Gefährten. Sein Werk ist in polemischem Stil gegen die anderen Schulen argumentiert."],
    ar: ["ما منهج ابن حزم في الاستدلال الفقهي في «الإحكام»؟", ["أنكر القياس والاستحسان والتقليد وتمسك بظاهر النصوص وإجماع الصحابة", "قبل كل قياس بلا نص", "اعتمد على العرف وحده", "أنكر السنة مصدرًا"], "تمسكت المدرسة الظاهرية التي أسسها داود الظاهري ودافع عنها ابن حزم (ت 456هـ) في «الإحكام في أصول الأحكام» و«المحلى» بظاهر القرآن والسنة، ونفت حجية القياس والاستحسان والتقليد، وقصرت الإجماع على إجماع الصحابة، وكتبه مكتوبة بأسلوب جدلي ضد المذاهب."] },

  { id: "xuf-019", s: "fiqh", g: 4, d: 6, t: ["usul", "naskh", "conditions"], tr: ["jumhur"], src: "al-Shāfiʿī, al-Risāla; al-Ghazālī, al-Mustaṣfā; al-Āmidī, al-Iḥkām",
    en: ["According to the uṣūlīs, which of these is NOT an accepted condition of abrogation (naskh)?", ["That the abrogating text be read more often than the abrogated one", "That the two texts truly conflict and cannot be reconciled", "That the abrogating text be later", "That the abrogating text be at least equal in strength to the abrogated one"], "Uṣūlīs require that there is a true conflict that cannot be harmonised, that the abrogating text is later, and that it is at least of equal strength (a probable report cannot abrogate a definitive text in the majority view). Frequency of reading plays no part. Al-Shāfiʿī insisted that a text is abrogated only by a text, and he did not allow the Sunna to abrogate the Quran, a stance debated in the schools."],
    de: ["Welche dieser Bedingungen ist nach den Uṣūlīs KEINE anerkannte Bedingung der Aufhebung (naskh)?", ["Dass der aufhebende Text häufiger gelesen wird als der aufgehobene", "Dass die beiden Texte wirklich im Widerspruch stehen und nicht vereinbart werden können", "Dass der aufhebende Text später ist", "Dass der aufhebende Text mindestens gleich stark ist wie der aufgehobene"], "Die Uṣūlīs verlangen einen echten Widerspruch, der sich nicht vereinbaren lässt, dass der aufhebende Text später ist und dass er mindestens gleich stark ist (ein wahrscheinlicher Bericht kann nach Mehrheitsansicht keinen sicheren Text aufheben). Die Häufigkeit des Lesens spielt keine Rolle. Aš-Šāfiʿī bestand darauf, dass ein Text nur durch einen Text aufgehoben wird, und er erlaubte nicht, dass die Sunna den Koran aufhebt, eine in den Schulen debattierte Haltung."],
    ar: ["أي مما يأتي ليس شرطًا معتبرًا في النسخ عند الأصوليين؟", ["أن يكون الناسخ أكثر قراءة من المنسوخ", "أن يتعارض النصان تعارضًا حقيقيًّا لا يمكن الجمع بينهما", "أن يكون الناسخ متأخرًا", "أن يكون الناسخ مساويًا في القوة أو أقوى"], "اشترط الأصوليون تعارضًا حقيقيًّا لا يمكن معه الجمع وتأخر الناسخ ومساواته للمنسوخ في القوة أو زيادته (فلا ينسخ الظني القطعي عند الأكثر)، وكثرة القراءة لا أثر لها، وأصر الشافعي على أن النص لا ينسخه إلا نص ومنع نسخ السنة للقرآن وهي مسألة خلافية بين المذاهب."] },

  { id: "xuf-020", s: "fiqh", g: 4, d: 7, t: ["usul", "tarjih", "conflict"], tr: ["hanafi", "comparative"], src: "al-Sarakhsī, Uṣūl; al-Āmidī, al-Iḥkām; al-Zuḥaylī, Uṣūl al-Fiqh al-Islāmī",
    en: ["How does the Ḥanafī method order the handling of two conflicting texts, as against the majority?", ["The Ḥanafīs order it as abrogation, then preference (tarjīḥ), then harmonisation, then dropping the two; the majority generally start with harmonisation (jamʿ) where possible", "The Ḥanafīs start with dropping both texts; the majority drop one", "Both start with preferring the more frequent text", "Both call a vote among scholars"], "Ḥanafī uṣūl follows the order naskh, tarjīḥ, jamʿ and then tasāquṭ (dropping both), whereas the majority of the Shāfiʿīs, Mālikīs and Ḥanbalīs generally prefer harmonisation first as it gives both texts effect, and then abrogation, then tarjīḥ. The difference stems from their view that harmonisation can reduce the force of a text."],
    de: ["Wie ordnet die ḥanafitische Methode den Umgang mit zwei einander widersprechenden Texten im Gegensatz zur Mehrheit?", ["Die Ḥanafiten ordnen: Aufhebung, dann Bevorzugung (tarǧīḥ), dann Vereinbarung, dann Verwerfen beider; die Mehrheit beginnt im Allgemeinen mit der Vereinbarung (ǧamʿ), wo möglich", "Die Ḥanafiten beginnen mit dem Verwerfen beider Texte; die Mehrheit verwirft einen", "Beide beginnen mit der Bevorzugung des häufigeren Textes", "Beide veranstalten eine Abstimmung unter Gelehrten"], "Die ḥanafitische Uṣūl folgt der Reihenfolge Naskh, Tarǧīḥ, Ǧamʿ und dann Tasāquṭ (Verwerfen beider), während die Mehrheit der Šāfiʿiten, Mālikiten und Ḥanbaliten im Allgemeinen zuerst die Vereinbarung bevorzugt, weil sie beiden Texten Wirkung gibt, dann die Aufhebung, dann den Tarǧīḥ. Der Unterschied rührt von ihrer Ansicht, dass Vereinbarung die Kraft eines Textes mindern kann."],
    ar: ["كيف يرتب الحنفية التعامل مع نصين متعارضين خلافًا للجمهور؟", ["يرتب الحنفية: النسخ ثم الترجيح ثم الجمع ثم تساقط الدليلين، والجمهور عمومًا يبدؤون بالجمع إن أمكن", "يبدأ الحنفية بإسقاط النصين والجمهور يسقطون أحدهما", "كلاهما يبدأ بتقديم الأكثر تكرارًا", "كلاهما يجري تصويتًا بين العلماء"], "ترتيب الحنفية النسخ فالترجيح فالجمع فالتساقط، أما جمهور الشافعية والمالكية والحنابلة فيقدمون الجمع أولًا لأن فيه إعمال الدليلين ثم النسخ ثم الترجيح، ومنشأ الفرق نظرهم إلى أن الجمع قد يضعف دلالة النص."] },

  { id: "xuf-021", s: "fiqh", g: 4, d: 6, t: ["usul", "ahkam", "five-rulings"], tr: ["hanafi", "jumhur"], src: "al-Ghazālī, al-Mustaṣfā; al-Zuḥaylī, al-Wajīz fī Uṣūl al-Fiqh; al-Sarakhsī, Uṣūl",
    en: ["Which list correctly gives the five rulings (al-aḥkām al-khamsa) used by the majority?", ["Wājib, mandūb, mubāḥ, makrūh and ḥarām", "Fard, sunna, wājib, ḥarām and makrūh only", "Ḥalāl, ḥarām, ṭāhir, najis and mubāḥ", "Aṣl, farʿ, ʿilla, ḥukm and shart"], "The majority list the five categories of the Sharia ruling as wājib (obligatory), mandūb (recommended), mubāḥ (permitted), makrūh (disliked) and ḥarām (forbidden). The Ḥanafīs expand to seven: fard, wājib, sunna (or mandūb), mubāḥ, makrūh tanzīhan, makrūh taḥrīman and ḥarām. The difference reflects their view of degrees of evidence."],
    de: ["Welche Liste gibt die fünf Urteilsstufen (al-aḥkām al-ḫamsa) der Mehrheit richtig an?", ["Wāǧib, mandūb, mubāḥ, makrūh und ḥarām", "Nur fard, sunna, wāǧib, ḥarām und makrūh", "Ḥalāl, ḥarām, ṭāhir, naǧis und mubāḥ", "Aṣl, farʿ, ʿilla, ḥukm und šarṭ"], "Die Mehrheit führt die fünf Kategorien des Scharia-Urteils auf: wāǧib (verpflichtend), mandūb (empfohlen), mubāḥ (erlaubt), makrūh (missbilligt) und ḥarām (verboten). Die Ḥanafiten erweitern auf sieben: fard, wāǧib, sunna (oder mandūb), mubāḥ, makrūh tanzīhan, makrūh taḥrīman und ḥarām. Der Unterschied spiegelt ihre Sicht der Beleggrade."],
    ar: ["أي قائمة تذكر الأحكام التكليفية الخمسة عند الجمهور على الوجه الصحيح؟", ["الواجب والمندوب والمباح والمكروه والحرام", "الفرض والسنة والواجب والحرام والمكروه فقط", "الحلال والحرام والطاهر والنجس والمباح", "الأصل والفرع والعلة والحكم والشرط"], "الأحكام التكليفية عند الجمهور خمسة: الواجب والمندوب والمباح والمكروه والحرام، ويزيد الحنفية فيجعلونها سبعة: الفرض والواجب والسنة (أو المندوب) والمباح والمكروه تنزيهًا والمكروه تحريمًا والحرام، تبعًا لنظرهم في مراتب الأدلة."] },

  { id: "xuf-022", s: "fiqh", g: 4, d: 7, t: ["usul", "fard-kifaya", "ayn"], tr: ["comparative"], src: "al-Ghazālī, al-Mustaṣfā; al-Juwaynī, al-Burhān; al-Zarkashī, al-Baḥr al-Muḥīṭ",
    en: ["What is the debate over the communal obligation (farḍ al-kifāya) among the uṣūlīs?", ["Whether the obligation is addressed to all and removed by some performing it (the majority), or addressed to an unspecified group; they agree that if no one performs it, all are sinful", "Whether it applies only to women", "Whether it is performed once a year", "Whether it applies only to the ruler"], "Farḍ kifāya (like funeral prayer or knowledge needed by the community) is a duty whose goal is that it be done, not who does it. The majority hold the address is to all, which lapses when enough people do it; al-Juwaynī and others discuss alternative explanations (an unspecified group, or those capable). All agree that the community is sinful if it is left undone."],
    de: ["Was ist die Debatte der Uṣūlīs über die Gemeinschaftspflicht (farḍ al-kifāya)?", ["Ob die Pflicht an alle gerichtet ist und entfällt, wenn einige sie erfüllen (die Mehrheit), oder an eine unbestimmte Gruppe; sie stimmen überein, dass alle sündigen, wenn niemand sie erfüllt", "Ob sie nur für Frauen gilt", "Ob sie einmal im Jahr verrichtet wird", "Ob sie nur für den Herrscher gilt"], "Farḍ kifāya (wie das Totengebet oder für die Gemeinschaft nötiges Wissen) ist eine Pflicht, bei der es darauf ankommt, dass sie getan wird, nicht wer sie tut. Die Mehrheit hält, die Anrede gelte allen und entfalle, wenn genug Menschen sie erfüllen; al-Ǧuwainī und andere erörtern Alternativen (eine unbestimmte Gruppe oder die Fähigen). Alle stimmen überein, dass die Gemeinschaft sündigt, wenn sie unterbleibt."],
    ar: ["ما الخلاف بين الأصوليين في فرض الكفاية؟", ["هل الخطاب موجّه للجميع ويسقط بقيام بعضهم (الجمهور) أم لطائفة غير معينة، ويتفقون أنه إن لم يقم به أحد أثم الجميع", "هل يخص النساء فقط", "هل يؤدى مرة في السنة", "هل يخص الحاكم فقط"], "فرض الكفاية (كصلاة الجنازة والعلم اللازم للأمة) واجب يُقصد تحقيقه لا تعيين فاعله، والجمهور على أن الخطاب للجميع ويسقط بقيام من يكفي، وذكر الجويني وغيره تخريجات أخرى (طائفة مبهمة أو القادرون)، واتفقوا على إثم الأمة إذا تُرك."] },

  { id: "xuf-023", s: "fiqh", g: 4, d: 6, t: ["usul", "rukhsa-azima"], tr: ["comparative"], src: "al-Shāṭibī, al-Muwāfaqāt; al-Ghazālī, al-Mustaṣfā; al-Zuḥaylī, al-Wajīz fī Uṣūl al-Fiqh",
    en: ["What do ʿazīma and rukhṣa mean in uṣūl al-fiqh?", ["ʿAzīma is the original general ruling; rukhṣa is a concession allowed because of a difficulty or necessity, such as shortening prayer while travelling", "ʿAzīma is a recommended act; rukhṣa is a forbidden act", "ʿAzīma is a Quranic reading; rukhṣa is a hadith grade", "ʿAzīma is the call to prayer; rukhṣa is the sermon"], "ʿAzīma is the ruling as originally legislated for all. Rukhṣa is a ruling changed to ease because of an excuse (hardship, illness, travel, coercion), as in the shortening of prayer, breaking the fast of Ramadan for a traveller or eating carrion under necessity. The schools differ on whether taking the concession is obligatory, recommended or permitted, depending on the case, with the Ḥanafīs usually treating some as obligatory."],
    de: ["Was bedeuten ʿazīma und rukhṣa in der Uṣūl al-Fiqh?", ["ʿAzīma ist das ursprüngliche allgemeine Urteil; rukhṣa ist eine Erleichterung aufgrund von Schwierigkeit oder Not, etwa das Kürzen des Gebets auf Reisen", "ʿAzīma ist eine empfohlene Handlung; rukhṣa eine verbotene", "ʿAzīma ist eine Koranlesart; rukhṣa ein Hadithgrad", "ʿAzīma ist der Gebetsruf; rukhṣa die Predigt"], "ʿAzīma ist das Urteil, wie es ursprünglich für alle gesetzt wurde. Rukhṣa ist ein zur Erleichterung geändertes Urteil wegen eines Entschuldigungsgrundes (Härte, Krankheit, Reise, Zwang), etwa das Kürzen des Gebets, das Brechen des Ramadanfastens für einen Reisenden oder der Verzehr von Aas in Not. Die Schulen unterscheiden sich darin, ob die Inanspruchnahme je nach Fall Pflicht, Empfehlung oder erlaubt ist, wobei die Ḥanafiten manche meist als Pflicht behandeln."],
    ar: ["ماذا تعني العزيمة والرخصة في أصول الفقه؟", ["العزيمة الحكم الأصلي العام والرخصة حكم مخفف لعذر أو ضرورة كقصر الصلاة في السفر", "العزيمة عمل مندوب والرخصة عمل محرم", "العزيمة قراءة قرآنية والرخصة درجة حديثية", "العزيمة الأذان والرخصة الخطبة"], "العزيمة الحكم المشروع أصلًا لعامة المكلفين، والرخصة ما غُيّر إلى سهولة لعذر (مشقة أو مرض أو سفر أو إكراه) كقصر الصلاة وفطر المسافر وأكل الميتة للضرورة، ويختلفون في حكم الأخذ بالرخصة بين الوجوب والاستحباب والإباحة بحسب الحال، وقد يجعل الحنفية بعضها واجبًا."] },

  { id: "xuf-024", s: "fiqh", g: 4, d: 7, t: ["usul", "taklif", "ma-la-yutaq"], tr: ["ashari", "maturidi", "comparative"], src: "al-Juwaynī, al-Burhān; al-Ghazālī, al-Mustaṣfā; al-Āmidī, al-Iḥkām; al-Taftāzānī, Sharḥ al-Talwīḥ",
    en: ["What is the debate on taklīf mā lā yuṭāq (imposing what is beyond ability)?", ["Whether God could theoretically impose it; Ashʿarīs allowed it in principle without it occurring, while Muʿtazilīs and many Māturīdīs denied it", "Whether the Prophet could fast forever", "Whether unlimited prayer is required", "Whether prayer on a mountain is valid"], "The question is whether imposing something impossible is possible for God. Ashʿarīs, based on God’s absolute power, held it is possible rationally, though by the verse affirming that God does not burden a soul beyond its capacity it does not occur. The Muʿtazila and many Māturīdīs say it is not possible as it contradicts God’s justice. The discussion arose from questions such as the command to Abū Lahab to believe."],
    de: ["Was ist die Debatte über taklīf mā lā yuṭāq (Auferlegen des Unmöglichen)?", ["Ob Gott es theoretisch auferlegen könnte; die Ašʿariten erlaubten es grundsätzlich, ohne dass es vorkommt, während die Muʿtaziliten und viele Māturīditen es bestritten", "Ob der Prophet ewig fasten könnte", "Ob unbegrenztes Gebet verlangt wird", "Ob Gebet auf einem Berg gültig ist"], "Die Frage ist, ob das Auferlegen von etwas Unmöglichem für Gott möglich ist. Die Ašʿariten hielten es aufgrund von Gottes absoluter Macht verstandesmäßig für möglich, obwohl es nach dem Vers, der bekräftigt, dass Gott keiner Seele über ihr Vermögen auflädt, nicht vorkommt. Die Muʿtazila und viele Māturīditen sagen, es sei nicht möglich, da es Gottes Gerechtigkeit widerspräche. Die Erörterung entstand aus Fragen wie dem Befehl an Abū Lahab zu glauben."],
    ar: ["ما الخلاف في تكليف ما لا يطاق؟", ["هل يجوز عقلًا أن يكلف الله به؟ جوّزه الأشاعرة من حيث الأصل مع عدم وقوعه، ومنعه المعتزلة وكثير من الماتريدية", "هل يمكن للنبي ﷺ صيام الدهر", "هل تجب الصلاة بلا حد", "هل تصح الصلاة على الجبل"], "المسألة هل يجوز عقلًا أن يكلف الله بالمحال، فجوّزه الأشاعرة بناءً على تمام قدرته مع القول بعدم وقوعه للآية الدالة على أن الله لا يكلف نفسًا إلا وسعها، ومنعه المعتزلة وكثير من الماتريدية لتعارضه مع عدله، وأصل الكلام فيها من مسائل كتكليف أبي لهب بالإيمان."] },

  { id: "xuf-025", s: "fiqh", g: 4, d: 6, t: ["usul", "hukm-wad-i", "sabab-shart-mani"], tr: ["comparative"], src: "al-Qarāfī, al-Furūq; al-Zuḥaylī, al-Wajīz fī Uṣūl al-Fiqh; al-Shāṭibī, al-Muwāfaqāt",
    en: ["What is the distinction between a cause (sabab), a condition (sharṭ) and an impediment (māniʿ) in uṣūl?", ["A cause necessitates the ruling by its presence; a condition must be present but does not itself necessitate; an impediment prevents the ruling even when the cause is present", "A cause is a person; a condition is a place; an impediment is a time", "They are three names for the same thing", "A cause is voluntary; a condition is forbidden; an impediment is permitted"], "A sabab is a sign whose presence indicates the existence of the ruling and absence indicates its absence (the sunset for the sunset prayer). A sharṭ is what the ruling depends on without being a cause (ablution for prayer). A māniʿ prevents the effect even when the cause and the condition are present (such as debt for zakāt, or killing for inheritance). These form the declaratory rulings (al-ḥukm al-waḍʿī)."],
    de: ["Was ist der Unterschied zwischen Ursache (sabab), Bedingung (šarṭ) und Hindernis (māniʿ) in der Uṣūl?", ["Eine Ursache bedingt das Urteil durch ihr Vorhandensein; eine Bedingung muss vorhanden sein, bedingt aber nicht selbst; ein Hindernis verhindert das Urteil, auch wenn die Ursache vorhanden ist", "Eine Ursache ist eine Person; eine Bedingung ein Ort; ein Hindernis eine Zeit", "Es sind drei Namen für dasselbe", "Eine Ursache ist freiwillig; eine Bedingung verboten; ein Hindernis erlaubt"], "Ein Sabab ist ein Zeichen, dessen Vorhandensein die Existenz des Urteils und dessen Fehlen sein Fehlen anzeigt (der Sonnenuntergang für das Abendgebet). Ein Šarṭ ist, wovon das Urteil abhängt, ohne Ursache zu sein (die Waschung für das Gebet). Ein Māniʿ verhindert die Wirkung, selbst wenn Ursache und Bedingung vorliegen (etwa Schulden bei der Zakāt oder Tötung beim Erbe). Diese bilden die deklaratorischen Urteile (al-ḥukm al-waḍʿī)."],
    ar: ["ما الفرق بين السبب والشرط والمانع في الأصول؟", ["السبب يلزم من وجوده وجود الحكم، والشرط يلزم من عدمه عدم الحكم ولا يلزم من وجوده وجود، والمانع يمنع الحكم مع وجود السبب", "السبب شخص والشرط مكان والمانع زمان", "هي ثلاثة أسماء لشيء واحد", "السبب اختياري والشرط محرم والمانع مباح"], "السبب علامة يلزم من وجودها وجود الحكم ومن عدمها عدمه (غروب الشمس لصلاة المغرب)، والشرط ما يتوقف عليه الحكم وليس سببًا (الوضوء للصلاة)، والمانع ما يمنع أثر السبب مع وجود السبب والشرط (كالدين في الزكاة والقتل في الميراث)، وهذه هي الحكم الوضعي."] },

  { id: "xuf-026", s: "fiqh", g: 4, d: 7, t: ["usul", "ahliyya", "awaridh"], tr: ["hanafi", "comparative"], src: "al-Bazdawī, Kanz al-Wuṣūl; al-Sarakhsī, Uṣūl; al-Taftāzānī, Sharḥ al-Talwīḥ",
    en: ["What are the two kinds of legal capacity (ahliyya) distinguished in the Ḥanafī uṣūl?", ["Capacity for obligation (ahliyyat al-wujūb), which a person has from birth, and capacity for performance (ahliyyat al-adāʾ), which depends on reason", "Capacity for prayer and capacity for fasting", "Capacity of men and capacity of women", "Capacity of rulers and capacity of judges"], "The Ḥanafī manuals distinguish ahliyyat al-wujūb, based on the human soul (dhimma) and thus held by every human being including the foetus in limited form, from ahliyyat al-adāʾ, based on discernment and reason, which is incomplete in the discerning child and complete at puberty with sound reason. Impediments (ʿawāriḍ) such as madness, forgetfulness, sleep and compulsion affect them. The majority use similar ideas with different terms."],
    de: ["Welche beiden Arten der Rechtsfähigkeit (ahliyya) unterscheidet die ḥanafitische Uṣūl?", ["Die Fähigkeit zur Verpflichtung (ahliyyat al-wuǧūb), die man von Geburt an hat, und die Fähigkeit zur Ausführung (ahliyyat al-adāʾ), die vom Verstand abhängt", "Fähigkeit zum Gebet und Fähigkeit zum Fasten", "Fähigkeit der Männer und Fähigkeit der Frauen", "Fähigkeit der Herrscher und Fähigkeit der Richter"], "Die ḥanafitischen Handbücher unterscheiden Ahliyyat al-wuǧūb, die auf der menschlichen Seele (ḏimma) beruht und deshalb jeder Mensch einschließlich des Fötus in begrenzter Form hat, von Ahliyyat al-adāʾ, die auf Unterscheidungsfähigkeit und Verstand beruht und beim unterscheidungsfähigen Kind unvollständig und bei Mündigkeit mit gesundem Verstand vollständig ist. Hindernisse (ʿawāriḍ) wie Wahnsinn, Vergesslichkeit, Schlaf und Zwang wirken auf sie ein. Die Mehrheit gebraucht ähnliche Gedanken mit anderen Begriffen."],
    ar: ["ما نوعا الأهلية اللذان يميزهما أصول الحنفية؟", ["أهلية الوجوب وهي ثابتة للإنسان منذ ولادته، وأهلية الأداء وهي مبنية على العقل", "أهلية الصلاة وأهلية الصيام", "أهلية الرجال وأهلية النساء", "أهلية الحكام وأهلية القضاة"], "يفرق كتب الحنفية بين أهلية الوجوب المبنية على الذمة فتثبت لكل إنسان حتى الجنين على وجه محدود، وأهلية الأداء المبنية على التمييز والعقل وهي ناقصة في الصبي المميز وكاملة بالبلوغ مع سلامة العقل، وتعتريها عوارض كالجنون والنسيان والنوم والإكراه، وللجمهور أفكار قريبة بمصطلحات أخرى."] },

  { id: "xuf-027", s: "fiqh", g: 4, d: 6, t: ["usul", "maqasid", "daruriyyat"], tr: ["comparative"], src: "al-Ghazālī, al-Mustaṣfā; al-Shāṭibī, al-Muwāfaqāt; Ibn ʿĀshūr, Maqāṣid al-Sharīʿa al-Islāmiyya",
    en: ["Which classification of the Sharia’s purposes (maqāṣid) did al-Ghazālī and al-Shāṭibī develop?", ["Necessities (ḍarūriyyāt), needs (ḥājiyyāt) and refinements (taḥsīniyyāt), with the five necessities protecting religion, life, intellect, lineage and property", "Rights of God, rights of rulers and rights of animals", "Prayer, fasting, zakāt and ḥajj", "Fard, wājib, sunna and mandūb"], "Al-Ghazālī presented the five necessities as the preserved goals of the Sharia, and al-Shāṭibī in al-Muwāfaqāt arranged the purposes in three levels: ḍarūriyyāt (necessities), ḥājiyyāt (needs) and taḥsīniyyāt (embellishments). Some later scholars add the protection of honour (ʿirḍ). Ibn ʿĀshūr later widened the study in the 20th century."],
    de: ["Welche Einteilung der Ziele der Scharia (maqāṣid) entwickelten al-Ġazālī und aš-Šāṭibī?", ["Notwendigkeiten (ḍarūriyyāt), Bedürfnisse (ḥāǧiyyāt) und Verfeinerungen (taḥsīniyyāt), wobei die fünf Notwendigkeiten Religion, Leben, Verstand, Abstammung und Besitz schützen", "Rechte Gottes, Rechte der Herrscher und Rechte der Tiere", "Gebet, Fasten, Zakāt und Ḥaǧǧ", "Fard, wāǧib, sunna und mandūb"], "Al-Ġazālī stellte die fünf Notwendigkeiten als die bewahrten Ziele der Scharia dar, und aš-Šāṭibī ordnete in al-Muwāfaqāt die Ziele in drei Stufen: ḍarūriyyāt (Notwendigkeiten), ḥāǧiyyāt (Bedürfnisse) und taḥsīniyyāt (Verfeinerungen). Manche spätere Gelehrte fügen den Schutz der Ehre (ʿirḍ) hinzu. Ibn ʿĀšūr erweiterte das Studium später im 20. Jahrhundert."],
    ar: ["أي تصنيف لمقاصد الشريعة وضعه الغزالي والشاطبي؟", ["الضروريات والحاجيات والتحسينيات، والضروريات الخمس حفظ الدين والنفس والعقل والنسل والمال", "حقوق الله وحقوق الحكام وحقوق الحيوان", "الصلاة والصيام والزكاة والحج", "الفرض والواجب والسنة والمندوب"], "عرض الغزالي الضروريات الخمس مقاصد محفوظة في الشرائع، ورتب الشاطبي في «الموافقات» المقاصد في ثلاث مراتب: الضروريات والحاجيات والتحسينيات، وأضاف بعض المتأخرين حفظ العرض، ثم توسع ابن عاشور في دراستها في القرن العشرين."] },

  { id: "xuf-028", s: "fiqh", g: 4, d: 7, t: ["usul", "ijtihad", "taqlid"], tr: ["comparative"], src: "al-Shāfiʿī, al-Risāla; al-Ghazālī, al-Mustaṣfā; al-Suyūṭī, al-Radd ʿalā man Akhlada ilā al-Arḍ; Ibn al-Ṣalāḥ, Adab al-Muftī",
    en: ["What disagreement exists about the 'closing of the gate of ijtihād'?", ["Some later jurists held that independent ijtihād ended with the founding imams, while others, such as al-Suyūṭī and Ibn Taymiyya, rejected that and held that every age must have its mujtahids", "All scholars agree it was closed in 300 AH", "All scholars agree it can never be closed", "The Quran explicitly closes it"], "The idea that unrestricted ijtihād ceased in the fourth century is the position of some late jurists who feared disorder and promoted taqlīd to the four schools. Many scholars rejected it, among them Ibn Taymiyya and al-Suyūṭī, who wrote a treatise against those who clung to the earth, claiming that the earth is never empty of a mujtahid. Modern historians also question whether it was ever formally closed."],
    de: ["Welche Meinungsverschiedenheit besteht über das ‚Schließen des Tores des Iǧtihād‘?", ["Manche spätere Juristen hielten, der unabhängige Iǧtihād habe mit den Gründungsimamen geendet, während andere wie as-Suyūṭī und Ibn Taimiyya das ablehnten und hielten, jedes Zeitalter müsse seine Mudschtahids haben", "Alle Gelehrten stimmen überein, dass es 300 n. H. geschlossen wurde", "Alle Gelehrten stimmen überein, dass es nie geschlossen werden kann", "Der Koran schließt es ausdrücklich"], "Die Vorstellung, dass der uneingeschränkte Iǧtihād im vierten Jahrhundert endete, ist die Position mancher später Juristen, die Unordnung fürchteten und den Taqlīd an die vier Schulen förderten. Viele Gelehrte lehnten sie ab, darunter Ibn Taimiyya und as-Suyūṭī, der eine Abhandlung gegen jene schrieb, die an der Erde klebten, und behauptete, die Erde sei nie ohne einen Mudschtahid. Auch moderne Historiker fragen, ob er je förmlich geschlossen wurde."],
    ar: ["ما الخلاف في «إغلاق باب الاجتهاد»؟", ["رأى بعض الفقهاء المتأخرين أن الاجتهاد المطلق انتهى بالأئمة المؤسسين، وردّ ذلك آخرون كالسيوطي وابن تيمية وقالوا لا بد لكل عصر من مجتهدين", "اتفق العلماء على إغلاقه سنة 300هـ", "اتفق العلماء على أنه لا يُغلق أبدًا", "القرآن يغلقه صراحة"], "ذهب بعض متأخري الفقهاء إلى انقطاع الاجتهاد المطلق منذ القرن الرابع خوف الفوضى ودعوا إلى التقليد في المذاهب الأربعة، وردّه كثيرون منهم ابن تيمية والسيوطي الذي ألّف رسالة في الرد على من أخلد إلى الأرض مقررًا أن الأرض لا تخلو من مجتهد، ويشكك المؤرخون المحدثون في أنه أُغلق رسميًّا."] },

  { id: "xuf-029", s: "fiqh", g: 4, d: 6, t: ["usul", "khabar-wahid"], tr: ["hanafi", "maliki", "comparative"], src: "al-Sarakhsī, Uṣūl; al-Shīrāzī, al-Lumaʿ; al-Shāfiʿī, al-Risāla; al-Shāṭibī, al-Muwāfaqāt",
    en: ["How did the schools differ on using a single-narrator report (khabar al-wāḥid) in law?", ["The majority accept it as evidence for rulings; the Ḥanafīs set conditions, such as that it does not contradict a more widely known practice, and some Mālikīs preferred Madinan practice when it conflicts", "All schools reject it", "All schools accept it for creed only", "Only the Ẓāhirīs accept it"], "The jurists, with scholars like al-Shāfiʿī, accepted the sound single-narrator report as proof of legal rulings. The Ḥanafīs required that it not contradict the Quran’s apparent meaning, a widely known sunna or the narrator’s own contrary practice, and concerning matters of general concern they asked for widespread transmission. The Mālikīs in cases of conflict with the practice of Madīna gave weight to the practice."],
    de: ["Wie unterschieden sich die Schulen bei der Verwendung eines Einzelberichts (ḫabar al-wāḥid) im Recht?", ["Die Mehrheit akzeptiert ihn als Beleg für Urteile; die Ḥanafiten setzen Bedingungen, etwa dass er keiner bekannteren Praxis widerspricht, und manche Mālikiten bevorzugten bei Widerspruch die medinensische Praxis", "Alle Schulen lehnen ihn ab", "Alle Schulen akzeptieren ihn nur für den Glauben", "Nur die Ẓāhiriten akzeptieren ihn"], "Die Juristen, mit Gelehrten wie aš-Šāfiʿī, akzeptierten den gesunden Einzelbericht als Beleg für Rechtsurteile. Die Ḥanafiten verlangten, dass er dem offenkundigen Sinn des Korans, einer weithin bekannten Sunna oder der gegenteiligen Praxis des Überlieferers selbst nicht widerspricht, und bei Dingen von allgemeinem Belang verlangten sie weite Verbreitung. Die Mālikiten gaben im Widerspruch mit der Praxis Medinas der Praxis Gewicht."],
    ar: ["كيف اختلفت المذاهب في الاحتجاج بخبر الواحد في الأحكام؟", ["قبله الجمهور حجة في الأحكام، ووضع الحنفية شروطًا كألا يخالف عملًا مشهورًا، وقدّم بعض المالكية عمل أهل المدينة عند التعارض", "ردته المذاهب كلها", "قبلته المذاهب كلها في العقيدة فقط", "قبله الظاهرية وحدهم"], "احتج الفقهاء ومنهم الشافعي بخبر الآحاد الصحيح في الأحكام، واشترط الحنفية ألا يخالف ظاهر القرآن أو سنة مشهورة أو عمل الراوي، وطلبوا الاستفاضة فيما تعم به البلوى، وقدم المالكية عند التعارض عمل أهل المدينة."] },

  { id: "xuf-030", s: "fiqh", g: 4, d: 7, t: ["usul", "ijtihad", "mukhti-musib"], tr: ["comparative", "ashari"], src: "al-Ghazālī, al-Mustaṣfā; al-Shīrāzī, al-Lumaʿ; al-Āmidī, al-Iḥkām",
    en: ["What is the debate on whether every mujtahid is correct (taṣwīb al-mujtahidīn)?", ["Whether all mujtahids are correct (al-muṣawwiba) or only one is correct and the other is mistaken but rewarded; most jurists held that only one is correct in God’s knowledge, with the mistaken still rewarded once", "Whether mujtahids may take wages", "Whether mujtahids must be men", "Whether mujtahids may travel"], "The Muṣawwiba (including some Ashʿarīs and Muʿtazilīs) held that every mujtahid is correct since God’s ruling follows the mujtahid’s result. The majority hold that there is one correct answer with God, so the right one gets two rewards and the mistaken one gets one, as in the well-known Prophetic statement about the judge. The hadith is reported with differing wording but is widely used in this discussion."],
    de: ["Was ist die Debatte, ob jeder Mudschtahid recht hat (taṣwīb al-muǧtahidīn)?", ["Ob alle Mudschtahids recht haben (al-muṣawwiba) oder nur einer recht hat und der andere irrt, aber belohnt wird; die meisten Juristen hielten, dass bei Gott nur einer recht hat, der Irrende aber einmal belohnt wird", "Ob Mudschtahids Lohn nehmen dürfen", "Ob Mudschtahids Männer sein müssen", "Ob Mudschtahids reisen dürfen"], "Die Muṣawwiba (darunter manche Ašʿariten und Muʿtaziliten) hielten, jeder Mudschtahid habe recht, da Gottes Urteil dem Ergebnis des Mudschtahids folgt. Die Mehrheit hält, dass es bei Gott eine richtige Antwort gibt, sodass der Richtige zwei Belohnungen und der Irrende eine erhält, wie in der bekannten prophetischen Aussage über den Richter. Der Hadith wird mit unterschiedlichem Wortlaut berichtet, wird aber in dieser Erörterung weithin gebraucht."],
    ar: ["ما الخلاف في تصويب المجتهدين؟", ["هل كل مجتهد مصيب (المصوِّبة) أم المصيب واحد والمخطئ مأجور؟ ذهب أكثر الفقهاء إلى أن المصيب واحد عند الله وللمخطئ أجر", "هل يأخذ المجتهد أجرًا", "هل يشترط أن يكون المجتهد رجلًا", "هل يسافر المجتهد"], "قال المصوِّبة (ومنهم بعض الأشاعرة والمعتزلة) إن كل مجتهد مصيب لأن حكم الله تابع لاجتهاد المجتهد، وقال الجمهور إن الحق عند الله واحد فللمصيب أجران وللمخطئ أجر كما في الحديث المعروف عن الحاكم، وهو مروي بألفاظ متعددة ومعتمد في هذا الباب."] },

  { id: "xuf-031", s: "fiqh", g: 4, d: 6, t: ["usul", "classical-works", "madhhab-methods"], tr: ["comparative"], src: "Ḥājjī Khalīfa, Kashf al-Ẓunūn; al-Zuḥaylī, Uṣūl al-Fiqh al-Islāmī; Ibn Khaldūn, Muqaddima",
    en: ["Which of these correctly distinguishes the two methods of writing uṣūl al-fiqh?", ["The way of the theologians (mutakallimūn) builds rules by proof independent of branch rulings (e.g. al-Mustaṣfā); the Ḥanafī way derives rules from the branch rulings of the founders (e.g. Uṣūl al-Sarakhsī)", "One is written in prose and the other only in poetry", "One is for men and the other for women", "One is for prayer and the other for trade"], "Ibn Khaldūn and others describe two methods: the Shāfiʿī path of the mutakallimūn, writing rules abstractly through proofs (al-Mustaṣfā, al-Burhān, al-Iḥkām), and the Ḥanafī path of the fuqahāʾ, extracting rules from the rulings of Abū Ḥanīfa and his students (Uṣūl al-Sarakhsī and al-Bazdawī). Later works like Ibn al-Sāʿātī’s Badīʿ al-Niẓām combined both."],
    de: ["Welche Aussage unterscheidet die beiden Methoden des Schreibens der Uṣūl al-Fiqh richtig?", ["Der Weg der Theologen (mutakallimūn) baut Regeln durch Beweis unabhängig von Einzelurteilen auf (z. B. al-Mustaṣfā); der ḥanafitische Weg leitet Regeln aus den Einzelurteilen der Gründer ab (z. B. Uṣūl as-Saraḫsī)", "Die eine ist in Prosa, die andere nur in Dichtung geschrieben", "Die eine ist für Männer, die andere für Frauen", "Die eine ist für das Gebet, die andere für den Handel"], "Ibn Ḫaldūn und andere beschreiben zwei Methoden: den šāfiʿitischen Weg der Mutakallimūn, der Regeln abstrakt durch Beweise schreibt (al-Mustaṣfā, al-Burhān, al-Iḥkām), und den ḥanafitischen Weg der Fuqahāʾ, der Regeln aus den Urteilen Abū Ḥanīfas und seiner Schüler gewinnt (Uṣūl as-Saraḫsī und al-Bazdawī). Spätere Werke wie Ibn as-Sāʿātīs Badīʿ an-Niẓām verbanden beide."],
    ar: ["أي عبارة تفرّق على الوجه الصحيح بين طريقتي التأليف في أصول الفقه؟", ["طريقة المتكلمين تبني القواعد بالدليل مستقلة عن الفروع كالمستصفى، وطريقة الحنفية تستخرج القواعد من فروع الأئمة كأصول السرخسي", "إحداهما بالنثر والأخرى بالشعر فقط", "إحداهما للرجال والأخرى للنساء", "إحداهما للصلاة والأخرى للتجارة"], "يذكر ابن خلدون وغيره طريقتين: طريقة الشافعية والمتكلمين التي تقرر القواعد مجردة بالأدلة (المستصفى والبرهان والإحكام)، وطريقة الحنفية والفقهاء التي تستنبط القواعد من فروع أبي حنيفة وأصحابه (أصول السرخسي وكنز البزدوي)، ثم جمع بين الطريقتين متأخرون كابن الساعاتي في «بديع النظام»."] },

  { id: "xuf-032", s: "fiqh", g: 4, d: 7, t: ["usul", "classical-works", "risala"], tr: ["shafii"], src: "al-Shāfiʿī, al-Risāla; al-Juwaynī, al-Burhān; al-Ghazālī, al-Mustaṣfā; al-Rāzī, al-Maḥṣūl",
    en: ["Which sequence of works marks the development of Shāfiʿī and theological uṣūl?", ["al-Shāfiʿī’s al-Risāla, al-Juwaynī’s al-Burhān, al-Ghazālī’s al-Mustaṣfā and al-Rāzī’s al-Maḥṣūl", "al-Ṭabarī’s Jāmiʿ, al-Bukhārī’s Ṣaḥīḥ, Muslim’s Ṣaḥīḥ and Abū Dāwūd’s Sunan", "al-Mubarrad’s al-Kāmil, Sībawayh’s al-Kitāb, al-Zamakhsharī’s al-Mufaṣṣal and Ibn Mālik’s Alfiyya", "Ibn Isḥāq’s Sīra, al-Wāqidī’s Maghāzī, Ibn Hishām’s Sīra and al-Ṭabarī’s Taʾrīkh"], "Al-Shāfiʿī’s al-Risāla is usually called the first book of uṣūl al-fiqh. Al-Juwaynī’s al-Burhān, his student al-Ghazālī’s al-Mustaṣfā and Fakhr al-Dīn al-Rāzī’s al-Maḥṣūl represent the developed theological method. Al-Āmidī’s al-Iḥkām and al-Isnawī’s Nihāyat al-Sūl follow it. These works shaped later textbooks."],
    de: ["Welche Werkreihe markiert die Entwicklung der šāfiʿitischen und theologischen Uṣūl?", ["Aš-Šāfiʿīs ar-Risāla, al-Ǧuwainīs al-Burhān, al-Ġazālīs al-Mustaṣfā und ar-Rāzīs al-Maḥṣūl", "Aṭ-Ṭabarīs Ǧāmiʿ, al-Buḫārīs Ṣaḥīḥ, Muslims Ṣaḥīḥ und Abū Dāwūds Sunan", "Al-Mubarrads al-Kāmil, Sībawaihs al-Kitāb, az-Zamaḫšarīs al-Mufaṣṣal und Ibn Māliks Alfiyya", "Ibn Isḥāqs Sīra, al-Wāqidīs Maġāzī, Ibn Hišāms Sīra und aṭ-Ṭabarīs Taʾrīḫ"], "Aš-Šāfiʿīs ar-Risāla gilt meist als das erste Buch der Uṣūl al-Fiqh. Al-Ǧuwainīs al-Burhān, das al-Mustaṣfā seines Schülers al-Ġazālī und Faḫr ad-Dīn ar-Rāzīs al-Maḥṣūl stehen für die entwickelte theologische Methode. Al-Āmidīs al-Iḥkām und al-Isnawīs Nihāyat as-Sūl folgen ihr. Diese Werke prägten spätere Lehrbücher."],
    ar: ["أي تسلسل لكتب يمثل تطور أصول الفقه الشافعية والكلامية؟", ["«الرسالة» للشافعي و«البرهان» للجويني و«المستصفى» للغزالي و«المحصول» للرازي", "«جامع» الطبري و«صحيح» البخاري و«صحيح» مسلم و«سنن» أبي داود", "«الكامل» للمبرد و«كتاب» سيبويه و«المفصل» للزمخشري و«ألفية» ابن مالك", "«سيرة» ابن إسحاق و«مغازي» الواقدي و«سيرة» ابن هشام و«تاريخ» الطبري"], "تُعد «الرسالة» للشافعي أول كتاب في أصول الفقه، ويمثل «البرهان» للجويني و«المستصفى» لتلميذه الغزالي و«المحصول» لفخر الدين الرازي المنهج الكلامي المتطور، ويتبعها «الإحكام» للآمدي و«نهاية السول» للإسنوي، وقد صاغت هذه الكتب المتون المتأخرة."] },

  { id: "xuf-033", s: "fiqh", g: 4, d: 6, t: ["usul", "qawaid-fiqhiyya"], tr: ["comparative"], src: "al-Suyūṭī, al-Ashbāh wa-l-Naẓāʾir; Ibn Nujaym, al-Ashbāh wa-l-Naẓāʾir; Majallat al-Aḥkām al-ʿAdliyya",
    en: ["What are the 'five great maxims' (al-qawāʿid al-kubrā) of legal maxims commonly listed in al-Suyūṭī’s al-Ashbāh wa-l-Naẓāʾir?", ["Matters are judged by their intentions; certainty is not removed by doubt; hardship brings ease; harm is to be removed; custom is a basis for judgement", "Prayer is a pillar; fasting is a shield; zakāt purifies; ḥajj once; jihād by the ruler", "The Quran first; the Sunna second; consensus third; analogy fourth; custom fifth", "The oath on the denier; the proof on the claimant; the witness two; the judge one; the court open"], "Legal maxims summarise many branch rulings. The five commonly listed major maxims are: al-umūr bi-maqāṣidihā (actions by their intentions), al-yaqīn lā yazūl bi-l-shakk (certainty is not removed by doubt), al-mashaqqa tajlib al-taysīr (hardship brings ease), al-ḍarar yuzāl (harm is removed) and al-ʿāda muḥakkama (custom is authoritative). Al-Suyūṭī, Ibn Nujaym and the Ottoman Majalla use them."],
    de: ["Welche ‚fünf großen Maximen‘ (al-qawāʿid al-kubrā) der Rechtsmaximen werden üblicherweise in as-Suyūṭīs al-Ašbāh wa-n-Naẓāʾir aufgeführt?", ["Dinge werden nach ihren Absichten beurteilt; Gewissheit wird nicht durch Zweifel beseitigt; Härte bringt Erleichterung; Schaden ist zu beseitigen; Brauch ist Grundlage des Urteils", "Das Gebet ist eine Säule; das Fasten ein Schild; die Zakāt reinigt; der Ḥaǧǧ einmal; der Ǧihād durch den Herrscher", "Zuerst der Koran; zweitens die Sunna; drittens der Konsens; viertens die Analogie; fünftens der Brauch", "Der Eid auf den Leugnenden; der Beweis auf den Kläger; der Zeuge zwei; der Richter einer; das Gericht offen"], "Rechtsmaximen fassen viele Einzelurteile zusammen. Die fünf üblicherweise genannten großen Maximen sind: al-umūr bi-maqāṣidihā (Handlungen nach ihren Absichten), al-yaqīn lā yazūl biš-šakk (Gewissheit wird nicht durch Zweifel beseitigt), al-mašaqqa taǧlib at-taisīr (Härte bringt Erleichterung), aḍ-ḍarar yuzāl (Schaden wird beseitigt) und al-ʿāda muḥakkama (Brauch ist maßgeblich). As-Suyūṭī, Ibn Nuǧaim und die osmanische Maǧalla gebrauchen sie."],
    ar: ["ما القواعد الخمس الكبرى للقواعد الفقهية المشهورة في «الأشباه والنظائر» للسيوطي؟", ["الأمور بمقاصدها، واليقين لا يزول بالشك، والمشقة تجلب التيسير، والضرر يزال، والعادة محكمة", "الصلاة عماد، والصوم جنة، والزكاة طهور، والحج مرة، والجهاد مع الإمام", "القرآن أولًا والسنة ثانيًا والإجماع ثالثًا والقياس رابعًا والعرف خامسًا", "اليمين على من أنكر، والبينة على المدعي، والشهود اثنان، والقاضي واحد، والمحكمة علنية"], "القواعد الفقهية تجمع فروعًا كثيرة، والخمس الكبرى المشهورة: الأمور بمقاصدها، واليقين لا يزول بالشك، والمشقة تجلب التيسير، والضرر يزال، والعادة محكمة، وقد اعتمدها السيوطي وابن نجيم ومجلة الأحكام العدلية العثمانية."] },

  { id: "xuf-034", s: "fiqh", g: 4, d: 7, t: ["usul", "urf", "adah"], tr: ["hanafi", "maliki", "comparative"], src: "Ibn ʿĀbidīn, Nashr al-ʿArf; al-Qarāfī, al-Iḥkām fī Tamyīz al-Fatāwā ʿan al-Aḥkām; Ibn al-Qayyim, Iʿlām al-Muwaqqiʿīn",
    en: ["What is the role of custom (ʿurf) in legal reasoning, and what did al-Qarāfī and Ibn al-Qayyim say about fatwā?", ["Custom may specify general texts and determine undefined matters when it does not contradict a text; both said fatwās change with place, time and customs when the basis was custom", "Custom replaces the Quran", "Custom is always rejected", "Custom applies only in worship"], "ʿUrf, a recognised habit of a people, is accepted by most schools as a means to interpret undefined terms and measure obligations (such as the amount of maintenance) if it does not contradict a text. Al-Qarāfī and Ibn al-Qayyim stressed that fatwās founded on custom must be changed when customs change, while the text-based ruling stays. Ibn ʿĀbidīn wrote the treatise Nashr al-ʿArf on it."],
    de: ["Welche Rolle spielt der Brauch (ʿurf) in der Rechtsfindung, und was sagten al-Qarāfī und Ibn al-Qayyim zur Fatwā?", ["Brauch kann allgemeine Texte spezifizieren und Unbestimmtes bestimmen, wenn er keinem Text widerspricht; beide sagten, Fatwas ändern sich mit Ort, Zeit und Bräuchen, wenn der Brauch die Grundlage war", "Brauch ersetzt den Koran", "Brauch wird immer abgelehnt", "Brauch gilt nur im Gottesdienst"], "ʿUrf, eine anerkannte Gewohnheit eines Volkes, wird von den meisten Schulen als Mittel anerkannt, um unbestimmte Begriffe auszulegen und Verpflichtungen zu bemessen (etwa die Höhe des Unterhalts), wenn er keinem Text widerspricht. Al-Qarāfī und Ibn al-Qayyim betonten, dass auf Brauch gegründete Fatwas geändert werden müssen, wenn sich die Bräuche ändern, während das textgestützte Urteil bleibt. Ibn ʿĀbidīn schrieb darüber die Abhandlung Našr al-ʿArf."],
    ar: ["ما دور العرف في الاستنباط وماذا قال القرافي وابن القيم عن الفتوى؟", ["يخصص العرف العام ويحدد المبهم إن لم يخالف نصًّا، وقالا إن الفتوى تتغير بتغير الزمان والمكان والعرف إذا كان مبناها العرف", "العرف يحل محل القرآن", "العرف مرفوض دائمًا", "العرف في العبادات فقط"], "العرف عادة معتبرة عند قوم يقبلها أكثر المذاهب لتفسير الألفاظ المبهمة وتقدير الواجبات كمقدار النفقة إن لم يخالف نصًّا، وأكد القرافي وابن القيم أن الفتاوى المبنية على العرف تتغير بتغيره دون الحكم المبني على النص، وألّف ابن عابدين «نشر العرف» في ذلك."] },

  { id: "xuf-035", s: "fiqh", g: 4, d: 6, t: ["usul", "istishab"], tr: ["shafii", "hanbali", "hanafi", "comparative"], src: "al-Ghazālī, al-Mustaṣfā; Ibn al-Qayyim, Iʿlām al-Muwaqqiʿīn; al-Sarakhsī, Uṣūl",
    en: ["What is istiṣḥāb (presumption of continuity) and where do the schools differ?", ["Presuming that a state known to have existed continues until proven otherwise; Shāfiʿīs and Ḥanbalīs use it widely as proof, while Ḥanafīs generally accept it only to maintain an existing state, not to establish a new right", "A prayer done at dawn", "A form of consensus", "A kind of oath"], "Istiṣḥāb is the continuation of a previous ruling or state in the absence of evidence of change, as in the presumption of purity or innocence. Most Shāfiʿīs, Ḥanbalīs and Mālikīs use it as proof; the Ḥanafīs said it is a proof for repelling a claim (daf‘) but not for establishing a new claim (ithbāt), a distinction often cited in the case of the missing person."],
    de: ["Was ist Istiṣḥāb (Vermutung der Fortdauer), und wo unterscheiden sich die Schulen?", ["Die Vermutung, dass ein bekannter Zustand fortbesteht, bis das Gegenteil bewiesen ist; Šāfiʿiten und Ḥanbaliten gebrauchen ihn breit als Beleg, während Ḥanafiten ihn im Allgemeinen nur zur Aufrechterhaltung eines bestehenden Zustands akzeptieren, nicht zur Begründung eines neuen Rechts", "Ein im Morgengrauen verrichtetes Gebet", "Eine Form des Konsenses", "Eine Art Eid"], "Istiṣḥāb ist die Fortdauer eines früheren Urteils oder Zustands bei fehlendem Hinweis auf Änderung, wie bei der Vermutung der Reinheit oder Unschuld. Die meisten Šāfiʿiten, Ḥanbaliten und Mālikiten gebrauchen ihn als Beleg; die Ḥanafiten sagten, er sei ein Beleg zur Abwehr eines Anspruchs (daf‘), nicht zur Begründung eines neuen Anspruchs (iṯbāt), eine Unterscheidung, die oft beim Vermissten zitiert wird."],
    ar: ["ما الاستصحاب وفيم تختلف المذاهب؟", ["افتراض استمرار حال ثابتة حتى يثبت خلافها، ويحتج به الشافعية والحنابلة كثيرًا، ويقبله الحنفية عمومًا لدفع الدعوى لا لإثبات حق جديد", "صلاة تؤدى عند الفجر", "صورة من الإجماع", "نوع من اليمين"], "الاستصحاب إبقاء حكم أو حال سابقة ما لم يوجد دليل على تغيرها كاستصحاب الطهارة والبراءة، ويحتج به أكثر الشافعية والحنابلة والمالكية، ويرى الحنفية أنه حجة للدفع لا للإثبات، وهي تفرقة مشهورة في مسألة المفقود."] },

  { id: "xuf-036", s: "fiqh", g: 4, d: 7, t: ["usul", "hila", "makhrij"], tr: ["comparative", "hanafi", "maliki", "shafii", "hanbali"], src: "Ibn al-Qayyim, Iʿlām al-Muwaqqiʿīn; al-Shāṭibī, al-Muwāfaqāt; al-Shaybānī, Kitāb al-Makhārij fī al-Ḥiyal",
    en: ["What was the main objection of scholars like Ibn al-Qayyim to legal devices (ḥiyal)?", ["That they use lawful forms to reach a forbidden result, which defeats the purpose of the Sharia; the Ḥanafīs, with works on makhārij, allowed some forms, while the Mālikīs and Ḥanbalīs opposed them strongly", "That they are too expensive", "That they are written in Persian", "That they use the Quran as a poem"], "Ḥiyal are legal stratagems that reach an aim by a form that avoids the apparent prohibition. Ibn al-Qayyim devoted long sections of Iʿlām al-Muwaqqiʿīn to refuting them, citing the Prophet’s criticism of those who used tricks to evade God’s limits, and arguing that the intention defines the act. Ḥanafī works such as al-Shaybānī’s al-Makhārij fī al-Ḥiyal allowed those used to escape hardship, with conditions."],
    de: ["Was war der Haupteinwand von Gelehrten wie Ibn al-Qayyim gegen Rechtskniffe (ḥiyal)?", ["Dass sie erlaubte Formen nutzen, um ein verbotenes Ergebnis zu erreichen, was den Zweck der Scharia vereitelt; die Ḥanafiten erlaubten mit Werken über Maḫāriǧ einige Formen, während Mālikiten und Ḥanbaliten sie stark ablehnten", "Dass sie zu teuer sind", "Dass sie auf Persisch geschrieben sind", "Dass sie den Koran als Gedicht gebrauchen"], "Ḥiyal sind rechtliche Kunstgriffe, die ein Ziel durch eine Form erreichen, die das offenkundige Verbot umgeht. Ibn al-Qayyim widmete lange Abschnitte von Iʿlām al-Muwaqqiʿīn ihrer Widerlegung, führte die Kritik des Propheten an denen an, die mit Tricks Gottes Grenzen umgingen, und argumentierte, die Absicht bestimme die Handlung. Ḥanafitische Werke wie aš-Šaibānīs al-Maḫāriǧ fī l-Ḥiyal erlaubten solche zum Entkommen aus Härte, mit Bedingungen."],
    ar: ["ما الاعتراض الرئيس لعلماء مثل ابن القيم على الحيل الفقهية؟", ["أنها تستعمل صورة مشروعة للوصول إلى نتيجة محرمة فتفوّت مقصد الشريعة، وأجاز الحنفية بعض صورها في كتب المخارج وشدد المالكية والحنابلة في منعها", "أنها باهظة التكلفة", "أنها مكتوبة بالفارسية", "أنها تستعمل القرآن شعرًا"], "الحيل وسائل فقهية للوصول إلى غرض بصورة تتفادى الحرمة الظاهرة، وخصص ابن القيم في «إعلام الموقعين» فصولًا طويلة لردها محتجًّا بذم النبي ﷺ لمن تحايل على حدود الله وبأن النية تحدد الفعل، وأجازت كتب الحنفية كـ«المخارج في الحيل» للشيباني ما يُتخلص به من حرج بشروط."] },

  { id: "xuf-037", s: "fiqh", g: 4, d: 6, t: ["usul", "classical-works", "four-imams"], tr: ["comparative"], src: "Ibn Khallikān, Wafayāt al-Aʿyān; al-Dhahabī, Siyar Aʿlām al-Nubalāʾ; Ibn Farḥūn, al-Dībāj al-Mudhahhab",
    en: ["Which statement correctly pairs the founders of the four Sunni schools with their works or transmitted books?", ["Abū Ḥanīfa: al-Fiqh al-Akbar (attributed); Mālik: al-Muwaṭṭaʾ; al-Shāfiʿī: al-Umm and al-Risāla; Aḥmad: al-Musnad", "Abū Ḥanīfa: al-Umm; Mālik: al-Musnad; al-Shāfiʿī: al-Muwaṭṭaʾ; Aḥmad: al-Risāla", "Abū Ḥanīfa: al-Risāla; Mālik: al-Fiqh al-Akbar; al-Shāfiʿī: al-Musnad; Aḥmad: al-Muwaṭṭaʾ", "All four wrote exactly the same book"], "Abū Ḥanīfa’s school is built on the transmissions of his students (al-Shaybānī’s Zāhir al-Riwāya), and the creed al-Fiqh al-Akbar is attributed to him. Mālik’s al-Muwaṭṭaʾ is a hadith and fiqh book. Al-Shāfiʿī wrote al-Risāla (uṣūl) and al-Umm (fiqh, with transmission through al-Rabīʿ). Aḥmad’s Musnad is a hadith compilation rather than a fiqh text; his fiqh was recorded by his students."],
    de: ["Welche Aussage ordnet die Gründer der vier sunnitischen Schulen richtig ihren Werken oder überlieferten Büchern zu?", ["Abū Ḥanīfa: al-Fiqh al-Akbar (zugeschrieben); Mālik: al-Muwaṭṭaʾ; aš-Šāfiʿī: al-Umm und ar-Risāla; Aḥmad: al-Musnad", "Abū Ḥanīfa: al-Umm; Mālik: al-Musnad; aš-Šāfiʿī: al-Muwaṭṭaʾ; Aḥmad: ar-Risāla", "Abū Ḥanīfa: ar-Risāla; Mālik: al-Fiqh al-Akbar; aš-Šāfiʿī: al-Musnad; Aḥmad: al-Muwaṭṭaʾ", "Alle vier schrieben genau dasselbe Buch"], "Abū Ḥanīfas Schule beruht auf den Überlieferungen seiner Schüler (aš-Šaibānīs Ẓāhir ar-Riwāya), und das Glaubensbekenntnis al-Fiqh al-Akbar wird ihm zugeschrieben. Māliks al-Muwaṭṭaʾ ist ein Hadith- und Fiqh-Buch. Aš-Šāfiʿī schrieb ar-Risāla (Uṣūl) und al-Umm (Fiqh, überliefert über ar-Rabīʿ). Aḥmads Musnad ist eine Hadithsammlung und kein Fiqh-Text; seinen Fiqh zeichneten seine Schüler auf."],
    ar: ["أي عبارة تقرن مؤسسي المذاهب السنية الأربعة بكتبهم أو المنقولة عنهم على الوجه الصحيح؟", ["أبو حنيفة: الفقه الأكبر (منسوب)؛ مالك: الموطأ؛ الشافعي: الأم والرسالة؛ أحمد: المسند", "أبو حنيفة: الأم؛ مالك: المسند؛ الشافعي: الموطأ؛ أحمد: الرسالة", "أبو حنيفة: الرسالة؛ مالك: الفقه الأكبر؛ الشافعي: المسند؛ أحمد: الموطأ", "ألّف الأربعة كتابًا واحدًا"], "قام مذهب أبي حنيفة على مرويات أصحابه (ظاهر الرواية للشيباني) ويُنسب إليه «الفقه الأكبر»، و«الموطأ» لمالك كتاب حديث وفقه، وألّف الشافعي «الرسالة» (أصول) و«الأم» (فقه برواية الربيع)، و«المسند» لأحمد جامع للحديث لا كتاب فقه، وفقهه دوّنه تلاميذه."] },

  { id: "xuf-038", s: "fiqh", g: 4, d: 7, t: ["usul", "taqlid", "talfiq"], tr: ["comparative"], src: "Ibn ʿĀbidīn, Radd al-Muḥtār; al-Qarāfī, al-Iḥkām; al-Zuḥaylī, al-Fiqh al-Islāmī wa-Adillatuhu",
    en: ["What is talfīq, and how do jurists view it?", ["Combining the opinions of different schools in one act in a way that none of the schools would accept as valid; many jurists restrict or forbid it, while others allow it in cases of need", "A way of reciting the Quran", "A form of consensus", "A kind of dye"], "Talfīq arises when a person follows one school for one part of an act and another for another part, so the combination is valid under none (for example, taking ablution rules from one school and a touching rule from another so that neither would accept the prayer). Some jurists forbid it; others, especially later ones, allow it for need or ease, with conditions of sincerity and not chasing concessions (tatabbuʿ al-rukhaṣ)."],
    de: ["Was ist Talfīq, und wie sehen Juristen es?", ["Das Verbinden der Meinungen verschiedener Schulen in einer Handlung in einer Weise, die jede der Schulen als ungültig ansehen würde; viele Juristen beschränken oder verbieten es, andere erlauben es bei Bedarf", "Eine Art, den Koran zu rezitieren", "Eine Form des Konsenses", "Eine Art Farbstoff"], "Talfīq entsteht, wenn jemand für einen Teil einer Handlung einer Schule und für einen anderen Teil einer anderen folgt, sodass die Verbindung nach keiner gültig ist (etwa wenn man Waschungsregeln der einen und eine Berührungsregel der anderen Schule nimmt, sodass keine das Gebet anerkennen würde). Manche Juristen verbieten es; andere, besonders spätere, erlauben es bei Bedarf oder zur Erleichterung, unter Bedingungen der Aufrichtigkeit und ohne das Nachjagen von Erleichterungen (tatabbuʿ ar-ruḫaṣ)."],
    ar: ["ما التلفيق وكيف ينظر إليه الفقهاء؟", ["الجمع بين مذاهب في عمل واحد بصورة لا يقول بصحتها أي من المذاهب، ويمنعه أو يقيّده كثير من الفقهاء ويجيزه آخرون عند الحاجة", "طريقة في تلاوة القرآن", "صورة من الإجماع", "نوع من الأصباغ"], "التلفيق أن يقلد المكلف مذهبًا في جزء من العمل ومذهبًا آخر في جزء آخر فتنتج صورة لا يصححها أي من المذهبين (كأن يأخذ من مذهب أحكام الوضوء ومن آخر حكم اللمس فلا يقبل أحدهما صلاته)، ويمنعه بعض الفقهاء، ويجيزه آخرون خصوصًا المتأخرين للحاجة أو التيسير بشروط الإخلاص وعدم تتبع الرخص."] },

  { id: "xuf-039", s: "fiqh", g: 4, d: 6, t: ["usul", "classical-works", "ibn-taymiyya"], tr: ["hanbali"], src: "Ibn Taymiyya, Majmūʿ al-Fatāwā and Raf‘ al-Malām ʿan al-Aʾimma al-Aʿlām; Ibn al-Qayyim, Iʿlām al-Muwaqqiʿīn",
    en: ["What is Ibn Taymiyya’s Raf‘ al-Malām ʿan al-Aʾimma al-Aʿlām about?", ["It explains ten reasons why the jurist-imams may differ from a sound hadith, to defend them from blame while insisting that a sound hadith must be followed", "It rules that the imams are infallible", "It is a book of poetry in praise of the imams", "It ranks the schools by age"], "Raf‘ al-Malām lists reasons that a respected mujtahid may not have acted by a sound hadith (the hadith did not reach him, he held it weak, he understood it differently, he held it abrogated and so on). The treatise defends the imams from reproach but affirms that once a sound hadith is known its meaning must be followed. It is a classic on the ethics of disagreement."],
    de: ["Worum geht es in Ibn Taimiyyas Raf‘ al-Malām ʿan al-Aʾimma al-Aʿlām?", ["Es erklärt zehn Gründe, warum die Rechtsgelehrten-Imame von einem gesunden Hadith abweichen können, um sie vor Tadel zu schützen, und besteht zugleich darauf, dass ein gesunder Hadith befolgt werden muss", "Es urteilt, dass die Imame unfehlbar sind", "Es ist ein Gedichtband zum Lob der Imame", "Es ordnet die Schulen nach Alter"], "Raf‘ al-Malām zählt Gründe auf, warum ein angesehener Mudschtahid nicht nach einem gesunden Hadith gehandelt haben mag (der Hadith erreichte ihn nicht, er hielt ihn für schwach, er verstand ihn anders, er hielt ihn für aufgehoben und so weiter). Die Abhandlung verteidigt die Imame vor Vorwurf, bekräftigt aber, dass man einem bekannten gesunden Hadith im Sinn folgen muss. Sie ist ein Klassiker zur Ethik der Meinungsverschiedenheit."],
    ar: ["ما موضوع «رفع الملام عن الأئمة الأعلام» لابن تيمية؟", ["يبين أسباب مخالفة الأئمة المجتهدين لحديث صحيح دفاعًا عنهم مع التأكيد على وجوب اتباع الحديث الصحيح", "يقرر عصمة الأئمة", "ديوان شعر في مدح الأئمة", "يرتب المذاهب بحسب القدم"], "يعدد «رفع الملام» أسباب ترك مجتهد معتبر العمل بحديث صحيح (لم يبلغه أو ضعّفه أو فهمه على وجه آخر أو رآه منسوخًا ونحو ذلك)، ويدافع عن الأئمة ويقرر أن الحديث الصحيح إذا علم معناه وجب اتباعه، وهي رسالة كلاسيكية في أدب الخلاف."] },

  { id: "xuf-040", s: "fiqh", g: 4, d: 7, t: ["usul", "mashhur-madhhab", "ikhtilaf-rawayat"], tr: ["hanbali", "shafii", "maliki", "hanafi", "comparative"], src: "al-Mardāwī, al-Inṣāf; al-Nawawī, al-Majmūʿ, introduction; Ibn ʿĀbidīn, Radd al-Muḥtār, introduction",
    en: ["How do later jurists identify the 'preferred opinion' of a school (al-muʿtamad) when it has more than one opinion?", ["By the tarjīḥ of the school’s verifiers, such as al-Nawawī and al-Rāfiʿī for the Shāfiʿīs (the two shaykhs), Ibn ʿĀbidīn for the Ḥanafīs, Khalīl’s commentators for the Mālikīs and al-Mardāwī for the Ḥanbalīs", "By drawing lots", "By the opinion of the ruler of the time", "By the number of pages in a book"], "Each school has a body of conventions to identify its reliable view. In the Shāfiʿī school, the agreement of al-Nawawī and al-Rāfiʿī (al-shaykhān) is the basis, with al-Nawawī preferred when they differ; in the Ḥanafī school Ibn ʿĀbidīn’s Radd al-Muḥtār sets rules for tarjīḥ; in the Mālikī school Mukhtaṣar Khalīl with its commentators; in the Ḥanbalī school al-Mardāwī’s al-Inṣāf. These regulate fatwā within each school."],
    de: ["Wie ermitteln spätere Juristen die ‚bevorzugte Meinung‘ einer Schule (al-muʿtamad), wenn sie mehr als eine Meinung hat?", ["Durch den Tarǧīḥ der Prüfer der Schule, etwa an-Nawawī und ar-Rāfiʿī für die Šāfiʿiten (die beiden Scheichs), Ibn ʿĀbidīn für die Ḥanafiten, die Kommentatoren Ḫalīls für die Mālikiten und al-Mardāwī für die Ḥanbaliten", "Durch Losen", "Durch die Meinung des Herrschers der Zeit", "Durch die Seitenzahl eines Buches"], "Jede Schule hat ein Regelwerk, um ihre verlässliche Ansicht zu ermitteln. In der šāfiʿitischen Schule ist die Übereinstimmung von an-Nawawī und ar-Rāfiʿī (aš-šaiḫān) die Grundlage, wobei an-Nawawī bei Abweichung bevorzugt wird; in der ḥanafitischen Schule setzt Ibn ʿĀbidīns Radd al-Muḥtār Regeln für den Tarǧīḥ; in der mālikitischen Schule der Muḫtaṣar Ḫalīl mit seinen Kommentatoren; in der ḥanbalitischen Schule al-Mardāwīs al-Inṣāf. Diese regeln die Fatwa innerhalb jeder Schule."],
    ar: ["كيف يحدد الفقهاء المتأخرون القول المعتمد في المذهب إذا تعددت أقواله؟", ["بترجيح محققي المذهب كالنووي والرافعي عند الشافعية (الشيخين) وابن عابدين عند الحنفية وشراح خليل عند المالكية والمرداوي عند الحنابلة", "بالقرعة", "برأي حاكم الزمان", "بعدد صفحات الكتاب"], "لكل مذهب ضوابط لمعرفة المعتمد، فعند الشافعية المعتمد ما اتفق عليه النووي والرافعي (الشيخان) ويقدَّم النووي عند الاختلاف، وعند الحنفية قواعد الترجيح في «رد المحتار» لابن عابدين، وعند المالكية «مختصر خليل» وشروحه، وعند الحنابلة «الإنصاف» للمرداوي، وهي تضبط الفتوى داخل كل مذهب."] },
];
